-- Table: bk_settings
DROP TABLE IF EXISTS `bk_settings`;
CREATE TABLE `bk_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `business_types` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`business_types`)),
