-- Table: bookings
DROP TABLE IF EXISTS `bookings`;
CREATE TABLE `bookings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `Ref` varchar(192) DEFAULT NULL,
  `customer_id` int(11) NOT NULL,
  `product_id` int(11) DEFAULT NULL,
  `tray_id` int(11) DEFAULT NULL,
  `sales_person_id` int(11) DEFAULT NULL,
  `product_name` varchar(255) DEFAULT NULL,
  `product_description` text DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `booking_date` date NOT NULL,
  `booking_time` time NOT NULL,
  `booking_end_time` time DEFAULT NULL,
  `delivery_date` date DEFAULT NULL,
  `delivery_time` time DEFAULT NULL,
  `delivery_address` text DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  `status` varchar(50) NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `google_calendar_event_id` varchar(255) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `share_token` varchar(64) DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'staff',
  `booking_mode` varchar(10) DEFAULT NULL,
  `business_type` varchar(30) DEFAULT NULL,
  `staff_id` int(11) DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `seats` smallint(5) unsigned NOT NULL DEFAULT 1,
  `preferred_date` date DEFAULT NULL,
  `preferred_window` varchar(20) DEFAULT NULL,
  `request_fields` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`request_fields`)),
  `public_token` varchar(64) DEFAULT NULL,
  `hold_until` datetime DEFAULT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancelled_by` varchar(20) DEFAULT NULL,
  `cancel_reason` varchar(500) DEFAULT NULL,
  `ecommerce_client_id` int(11) DEFAULT NULL,
  `sale_id` int(11) DEFAULT NULL,
  `confirmed_by` int(11) DEFAULT NULL,
  `arrived_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `reminder_sent_at` datetime DEFAULT NULL,
  `proposed_date` date DEFAULT NULL,
  `proposed_time` char(5) DEFAULT NULL,
  `proposed_end_time` char(5) DEFAULT NULL,
  `proposed_staff_id` int(11) DEFAULT NULL,
  `proposed_at` datetime DEFAULT NULL,
  `proposal_note` varchar(500) DEFAULT NULL,
  `deposit_amount` decimal(12,3) DEFAULT NULL,
  `deposit_status` varchar(12) DEFAULT NULL,
  `deposit_paid` decimal(12,3) NOT NULL DEFAULT 0.000,
  `deposit_paid_at` datetime DEFAULT NULL,
  `deposit_gateway` varchar(20) DEFAULT NULL,
  `deposit_reference` varchar(191) DEFAULT NULL,
  `deposit_note` varchar(500) DEFAULT NULL,
  `crm_lead_id` int(11) DEFAULT NULL,
  `crm_deal_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `bookings_share_token_unique` (`share_token`),
  UNIQUE KEY `bookings_public_token` (`public_token`),
  KEY `bookings_customer_id` (`customer_id`),
  KEY `bookings_product_id` (`product_id`),
  KEY `bookings_tray_id` (`tray_id`),
  KEY `bookings_sales_person_id` (`sales_person_id`),
  KEY `bookings_source` (`source`),
  KEY `bookings_staff_id` (`staff_id`),
  KEY `bookings_warehouse_id` (`warehouse_id`),
  KEY `bookings_ecommerce_client_id` (`ecommerce_client_id`),
  KEY `bookings_date_status` (`booking_date`,`status`),
  KEY `bookings_sale_id` (`sale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: brands
DROP TABLE IF EXISTS `brands`;
CREATE TABLE `brands` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `woocommerce_id` bigint(20) unsigned DEFAULT NULL,
  `name` varchar(192) NOT NULL,
  `description` varchar(192) DEFAULT NULL,
  `image` varchar(192) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: cash_registers
DROP TABLE IF EXISTS `cash_registers`;
CREATE TABLE `cash_registers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(10) unsigned NOT NULL,
  `warehouse_id` int(10) unsigned NOT NULL,
  `opening_balance` decimal(15,2) NOT NULL,
  `closing_balance` decimal(15,2) DEFAULT NULL,
  `total_sales` decimal(15,2) NOT NULL DEFAULT 0.00,
  `cash_in` decimal(15,2) NOT NULL DEFAULT 0.00,
  `cash_out` decimal(15,2) NOT NULL DEFAULT 0.00,
  `difference` decimal(15,2) DEFAULT NULL,
  `status` enum('open','closed') NOT NULL DEFAULT 'open',
  `opened_at` datetime NOT NULL,
  `closed_at` datetime DEFAULT NULL,
