  CONSTRAINT `client_opening_balance_payments_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `client_opening_balance_payments_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`),
  CONSTRAINT `client_opening_balance_payments_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
