-- Table: clients
DROP TABLE IF EXISTS `clients`;
CREATE TABLE `clients` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `woocommerce_id` bigint(20) unsigned DEFAULT NULL,
  `sync_issue_type` varchar(64) DEFAULT NULL,
