  `name` varchar(191) NOT NULL,
  `firstname` varchar(191) DEFAULT NULL,
  `lastname` varchar(191) DEFAULT NULL,
  `code` int(11) NOT NULL,
  `email` varchar(191) DEFAULT NULL,
  `country` varchar(191) DEFAULT NULL,
  `city` varchar(191) DEFAULT NULL,
  `state` varchar(100) DEFAULT NULL,
  `zip` varchar(20) DEFAULT NULL,
  `phone` varchar(191) DEFAULT NULL,
  `tax_number` varchar(192) DEFAULT NULL,
  `adresse` varchar(191) DEFAULT NULL,
  `quickbooks_id` varchar(64) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `clients_quickbooks_id_index` (`quickbooks_id`),
  KEY `clients_phone_index` (`phone`),
  KEY `clients_code_index` (`code`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: collection_product
DROP TABLE IF EXISTS `collection_product`;
CREATE TABLE `collection_product` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `collection_id` bigint(20) unsigned NOT NULL,
  `product_id` int(11) NOT NULL,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `pinned` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `collection_product_collection_id_foreign` (`collection_id`),
  KEY `product_id` (`product_id`),
  CONSTRAINT `collection_product_collection_id_foreign` FOREIGN KEY (`collection_id`) REFERENCES `collections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `collection_product_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: collections
DROP TABLE IF EXISTS `collections`;
CREATE TABLE `collections` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `limit` int(10) unsigned NOT NULL DEFAULT 8,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `collections_slug_unique` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: combined_products
DROP TABLE IF EXISTS `combined_products`;
CREATE TABLE `combined_products` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `combined_product_id` int(11) NOT NULL,
  `quantity` double NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `combined_products_product_id` (`product_id`),
  KEY `combined_products_combined_product_id` (`combined_product_id`),
  CONSTRAINT `combined_products_combined_product_id_foreign` FOREIGN KEY (`combined_product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `combined_products_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: commission_programs
DROP TABLE IF EXISTS `commission_programs`;
CREATE TABLE `commission_programs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `description` varchar(500) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `rule_mode` varchar(32) NOT NULL DEFAULT 'all',
  `valid_from` date DEFAULT NULL,
  `valid_to` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: commission_receipts
DROP TABLE IF EXISTS `commission_receipts`;
CREATE TABLE `commission_receipts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `sales_agent_id` int(10) unsigned NOT NULL,
  `Ref` varchar(192) NOT NULL,
  `amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `paid_at` date NOT NULL,
  `payment_method_id` int(11) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `commission_receipts_ref_unique` (`Ref`),
  KEY `commission_receipts_sales_agent_id_index` (`sales_agent_id`),
  KEY `commission_receipts_payment_method_id_foreign` (`payment_method_id`),
  CONSTRAINT `commission_receipts_payment_method_id_foreign` FOREIGN KEY (`payment_method_id`) REFERENCES `payment_methods` (`id`) ON DELETE SET NULL,
  CONSTRAINT `commission_receipts_sales_agent_id_foreign` FOREIGN KEY (`sales_agent_id`) REFERENCES `sales_agents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: commission_rules
DROP TABLE IF EXISTS `commission_rules`;
CREATE TABLE `commission_rules` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `commission_program_id` int(10) unsigned NOT NULL,
  `name` varchar(191) NOT NULL,
  `type` varchar(32) NOT NULL DEFAULT 'percentage',
  `source` varchar(32) NOT NULL DEFAULT 'sale_total',
  `value` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `min_threshold` decimal(14,4) DEFAULT NULL,
  `max_cap` decimal(14,4) DEFAULT NULL,
  `applies_to` varchar(32) NOT NULL DEFAULT 'all_agents',
  `sales_agent_id` int(10) unsigned DEFAULT NULL,
  `priority` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `commission_rules_commission_program_id_index` (`commission_program_id`),
  KEY `commission_rules_sales_agent_id_index` (`sales_agent_id`),
  CONSTRAINT `commission_rules_commission_program_id_foreign` FOREIGN KEY (`commission_program_id`) REFERENCES `commission_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `commission_rules_sales_agent_id_foreign` FOREIGN KEY (`sales_agent_id`) REFERENCES `sales_agents` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: companies
DROP TABLE IF EXISTS `companies`;
CREATE TABLE `companies` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `email` varchar(191) DEFAULT NULL,
  `phone` varchar(191) DEFAULT NULL,
  `country` varchar(191) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_attachments
DROP TABLE IF EXISTS `contract_attachments`;
CREATE TABLE `contract_attachments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL,
  `file_name` varchar(191) NOT NULL,
  `file_path` varchar(191) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contract_attachments_contract_id_index` (`contract_id`),
  CONSTRAINT `contract_attachments_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_comments
DROP TABLE IF EXISTS `contract_comments`;
CREATE TABLE `contract_comments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `body` text NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contract_comments_contract_id_index` (`contract_id`),
  KEY `contract_comments_user_id_index` (`user_id`),
  CONSTRAINT `contract_comments_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contract_comments_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_notes
DROP TABLE IF EXISTS `contract_notes`;
CREATE TABLE `contract_notes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL,
  `user_id` int(11) NOT NULL,
  `content` text NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contract_notes_contract_id_index` (`contract_id`),
  KEY `contract_notes_user_id_index` (`user_id`),
  CONSTRAINT `contract_notes_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contract_notes_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_renewals
DROP TABLE IF EXISTS `contract_renewals`;
CREATE TABLE `contract_renewals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL,
  `renewed_from_contract_id` int(11) DEFAULT NULL,
  `renewal_date` date NOT NULL,
  `new_end_date` date NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contract_renewals_contract_id_index` (`contract_id`),
  KEY `contract_renewals_renewed_from_contract_id_index` (`renewed_from_contract_id`),
  CONSTRAINT `contract_renewals_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE,
  CONSTRAINT `contract_renewals_renewed_from_contract_id_foreign` FOREIGN KEY (`renewed_from_contract_id`) REFERENCES `contracts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_tasks
DROP TABLE IF EXISTS `contract_tasks`;
CREATE TABLE `contract_tasks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_id` int(11) NOT NULL,
  `title` varchar(191) NOT NULL,
  `due_date` date DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'pending',
  `description` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `contract_tasks_contract_id_index` (`contract_id`),
  CONSTRAINT `contract_tasks_contract_id_foreign` FOREIGN KEY (`contract_id`) REFERENCES `contracts` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contract_templates
DROP TABLE IF EXISTS `contract_templates`;
CREATE TABLE `contract_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `content` longtext DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: contracts
DROP TABLE IF EXISTS `contracts`;
CREATE TABLE `contracts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `contract_number` varchar(191) NOT NULL,
  `party_type` varchar(20) NOT NULL DEFAULT 'customer',
  `client_id` int(11) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `project_id` int(11) DEFAULT NULL,
  `subject` varchar(191) NOT NULL,
  `value` decimal(16,2) NOT NULL DEFAULT 0.00,
  `type` varchar(191) DEFAULT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `description` text DEFAULT NULL,
  `hide_from_customer` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(191) NOT NULL DEFAULT 'draft',
  `signer_name` varchar(191) DEFAULT NULL,
  `signed_at` timestamp NULL DEFAULT NULL,
  `signed_ip` varchar(45) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `contracts_contract_number_unique` (`contract_number`),
  KEY `contracts_client_id_index` (`client_id`),
  KEY `contracts_project_id_index` (`project_id`),
  KEY `contracts_employee_id_index` (`employee_id`),
  CONSTRAINT `contracts_client_fk` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `contracts_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `contracts_employee_fk` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `contracts_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: count_stock
DROP TABLE IF EXISTS `count_stock`;
CREATE TABLE `count_stock` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  `category_id` int(11) DEFAULT NULL,
  `file_stock` varchar(192) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `count_stock_user_id` (`user_id`),
  KEY `count_stock_warehouse_id` (`warehouse_id`),
  KEY `count_stock_category_id` (`category_id`),
  CONSTRAINT `count_stock_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `count_stock_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `count_stock_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: courier_accounts
DROP TABLE IF EXISTS `courier_accounts`;
CREATE TABLE `courier_accounts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `courier` varchar(50) NOT NULL,
  `name` varchar(120) NOT NULL,
  `mode` varchar(10) NOT NULL DEFAULT 'live',
  `credentials` text DEFAULT NULL,
  `settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`settings`)),
  `tracking_url` varchar(500) DEFAULT NULL,
  `pickup_contact` varchar(120) DEFAULT NULL,
  `pickup_phone` varchar(40) DEFAULT NULL,
  `pickup_address` varchar(500) DEFAULT NULL,
  `pickup_city` varchar(120) DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `default_weight` decimal(10,3) NOT NULL DEFAULT 0.500,
  `default_service` varchar(60) DEFAULT NULL,
  `allow_open_parcel` tinyint(1) NOT NULL DEFAULT 0,
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `webhook_token` varchar(64) NOT NULL,
  `last_tested_at` timestamp NULL DEFAULT NULL,
  `last_test_ok` tinyint(1) DEFAULT NULL,
  `last_test_message` varchar(500) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courier_accounts_webhook_token_unique` (`webhook_token`),
  KEY `courier_accounts_courier_index` (`courier`),
  KEY `courier_accounts_warehouse_id_index` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: courier_city_mappings
DROP TABLE IF EXISTS `courier_city_mappings`;
CREATE TABLE `courier_city_mappings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `courier` varchar(50) NOT NULL,
  `city_name` varchar(120) NOT NULL,
  `courier_city_code` varchar(100) DEFAULT NULL,
  `courier_city_name` varchar(150) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `courier_city_mappings_courier_city_name_unique` (`courier`,`city_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: courier_logs
DROP TABLE IF EXISTS `courier_logs`;
CREATE TABLE `courier_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `courier_account_id` bigint(20) unsigned DEFAULT NULL,
  `shipment_id` bigint(20) unsigned DEFAULT NULL,
  `courier` varchar(40) DEFAULT NULL,
  `action` varchar(30) NOT NULL,
  `direction` varchar(3) NOT NULL DEFAULT 'out',
  `level` varchar(10) NOT NULL DEFAULT 'info',
  `method` varchar(10) DEFAULT NULL,
  `url` varchar(500) DEFAULT NULL,
  `http_status` smallint(5) unsigned DEFAULT NULL,
  `duration_ms` int(10) unsigned DEFAULT NULL,
  `message` varchar(500) DEFAULT NULL,
  `request` text DEFAULT NULL,
  `response` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `courier_logs_courier_account_id_index` (`courier_account_id`),
  KEY `courier_logs_shipment_id_index` (`shipment_id`),
  KEY `courier_logs_action_index` (`action`),
  KEY `courier_logs_level_index` (`level`),
  KEY `courier_logs_created_at_index` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: courier_settings
DROP TABLE IF EXISTS `courier_settings`;
CREATE TABLE `courier_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `return_action` varchar(20) NOT NULL DEFAULT 'review',
  `cod_auto_record` tinyint(1) NOT NULL DEFAULT 1,
  `cod_account_id` int(11) DEFAULT NULL,
  `cod_payment_method_id` int(11) DEFAULT NULL,
  `charges_as_expense` tinyint(1) NOT NULL DEFAULT 0,
  `charges_expense_category_id` int(11) DEFAULT NULL,
  `sync_interval_minutes` smallint(5) unsigned NOT NULL DEFAULT 60,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `notify_sms` tinyint(1) NOT NULL DEFAULT 0,
  `notify_email` tinyint(1) NOT NULL DEFAULT 0,
  `notify_whatsapp` tinyint(1) NOT NULL DEFAULT 0,
  `notify_statuses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`notify_statuses`)),
  `notify_templates` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`notify_templates`)),
  `tracking_page` tinyint(1) NOT NULL DEFAULT 1,
  `risk_high_percent` tinyint(3) unsigned NOT NULL DEFAULT 30,
  `risk_min_shipments` tinyint(3) unsigned NOT NULL DEFAULT 3,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_activities
DROP TABLE IF EXISTS `crm_activities`;
CREATE TABLE `crm_activities` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `type` enum('call','meeting','email','note','task') NOT NULL DEFAULT 'task',
  `subject` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `status` enum('open','done') NOT NULL DEFAULT 'open',
  `priority` enum('low','normal','high') NOT NULL DEFAULT 'normal',
  `due_at` timestamp NULL DEFAULT NULL,
  `duration_minutes` smallint(5) unsigned DEFAULT NULL,
  `location` varchar(191) DEFAULT NULL,
  `outcome` varchar(30) DEFAULT NULL,
  `done_at` timestamp NULL DEFAULT NULL,
  `crm_lead_id` int(11) DEFAULT NULL,
  `crm_deal_id` int(11) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `owner_id` int(11) DEFAULT NULL,
  `reminder_minutes` smallint(5) unsigned DEFAULT NULL,
  `reminded_at` timestamp NULL DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `crm_activities_type_index` (`type`),
  KEY `crm_activities_status_index` (`status`),
  KEY `crm_activities_due_at_index` (`due_at`),
  KEY `crm_activities_done_at_index` (`done_at`),
  KEY `crm_activities_crm_lead_id_index` (`crm_lead_id`),
  KEY `crm_activities_crm_deal_id_index` (`crm_deal_id`),
  KEY `crm_activities_client_id_index` (`client_id`),
  KEY `crm_activities_owner_id_index` (`owner_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_assignment_rules
DROP TABLE IF EXISTS `crm_assignment_rules`;
CREATE TABLE `crm_assignment_rules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(160) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `conditions` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`conditions`)),
  `method` varchar(20) NOT NULL DEFAULT 'round_robin',
  `user_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`user_ids`)),
  `last_user_id` bigint(20) unsigned DEFAULT NULL,
  `assigned_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_contacts
DROP TABLE IF EXISTS `crm_contacts`;
CREATE TABLE `crm_contacts` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(11) NOT NULL,
  `name` varchar(191) NOT NULL,
  `job_title` varchar(120) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `phone` varchar(50) DEFAULT NULL,
  `is_primary` tinyint(1) NOT NULL DEFAULT 0,
  `notes` varchar(1000) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `crm_contacts_client_id_index` (`client_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_deal_events
DROP TABLE IF EXISTS `crm_deal_events`;
CREATE TABLE `crm_deal_events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `crm_deal_id` int(11) NOT NULL,
  `type` varchar(40) NOT NULL,
  `note` text DEFAULT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `user_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `crm_deal_events_crm_deal_id_index` (`crm_deal_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_deal_products
DROP TABLE IF EXISTS `crm_deal_products`;
CREATE TABLE `crm_deal_products` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `crm_deal_id` int(11) NOT NULL,
  `product_id` int(11) DEFAULT NULL,
  `product_variant_id` int(11) DEFAULT NULL,
  `name` varchar(191) NOT NULL,
  `code` varchar(191) DEFAULT NULL,
  `quantity` decimal(14,3) NOT NULL DEFAULT 1.000,
  `unit_price` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `tax_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `tax_method` tinyint(3) unsigned NOT NULL DEFAULT 1,
  `total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
