  UNIQUE KEY `crm_deals_deal_number_unique` (`deal_number`),
  KEY `crm_deals_title_index` (`title`),
  KEY `crm_deals_crm_pipeline_id_index` (`crm_pipeline_id`),
  KEY `crm_deals_crm_pipeline_stage_id_index` (`crm_pipeline_stage_id`),
  KEY `crm_deals_status_index` (`status`),
  KEY `crm_deals_crm_lead_id_index` (`crm_lead_id`),
  KEY `crm_deals_client_id_index` (`client_id`),
  KEY `crm_deals_owner_id_index` (`owner_id`),
  KEY `crm_deals_expected_close_date_index` (`expected_close_date`),
  KEY `crm_deals_quotation_id_index` (`quotation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: crm_lead_events
