  `marketing_opt_out` tinyint(1) NOT NULL DEFAULT 0,
  `marketing_opt_out_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `crm_leads_lead_number_unique` (`lead_number`),
  KEY `crm_leads_name_index` (`name`),
  KEY `crm_leads_email_index` (`email`),
  KEY `crm_leads_phone_normalized_index` (`phone_normalized`),
  KEY `crm_leads_crm_lead_source_id_index` (`crm_lead_source_id`),
  KEY `crm_leads_crm_lead_status_id_index` (`crm_lead_status_id`),
  KEY `crm_leads_owner_id_index` (`owner_id`),
  KEY `crm_leads_client_id_index` (`client_id`),
  KEY `crm_leads_last_activity_at_index` (`last_activity_at`),
  KEY `crm_leads_captured_via_index` (`captured_via`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


