  CONSTRAINT `deposits_account_id_foreign` FOREIGN KEY (`account_id`) REFERENCES `accounts` (`id`),
  CONSTRAINT `deposits_deposit_category_id_foreign` FOREIGN KEY (`deposit_category_id`) REFERENCES `deposit_categories` (`id`),
  CONSTRAINT `deposits_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: designations
DROP TABLE IF EXISTS `designations`;
CREATE TABLE `designations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `company_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `designation` varchar(192) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `designation_company_id` (`company_id`),
  KEY `designation_departement_id` (`department_id`),
  CONSTRAINT `designations_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `designations_department_id_foreign` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: dgi_documents
DROP TABLE IF EXISTS `dgi_documents`;
CREATE TABLE `dgi_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source_type` varchar(191) NOT NULL,
  `source_id` bigint(20) unsigned NOT NULL,
  `invoice_ref` varchar(191) DEFAULT NULL,
  `environment` varchar(20) NOT NULL DEFAULT 'test',
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `def_number` varchar(60) DEFAULT NULL,
  `counters` varchar(120) DEFAULT NULL,
  `auth_code` text DEFAULT NULL,
  `certified_at` datetime DEFAULT NULL,
  `qr_payload` text DEFAULT NULL,
  `errors` longtext DEFAULT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`payload`)),
  `response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`response`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `dgi_documents_source_type_source_id_unique` (`source_type`,`source_id`),
  KEY `dgi_documents_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: dgi_settings
DROP TABLE IF EXISTS `dgi_settings`;
CREATE TABLE `dgi_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `environment` varchar(20) NOT NULL DEFAULT 'test',
  `nif` varchar(30) DEFAULT NULL,
  `rccm` varchar(60) DEFAULT NULL,
  `id_nat` varchar(60) DEFAULT NULL,
  `company_name` varchar(200) DEFAULT NULL,
  `address` varchar(191) DEFAULT NULL,
  `def_number` varchar(60) DEFAULT NULL,
  `api_url` varchar(191) DEFAULT NULL,
  `api_token` longtext DEFAULT NULL,
  `tax_group_map` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tax_group_map`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: doctors
DROP TABLE IF EXISTS `doctors`;
CREATE TABLE `doctors` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `code` varchar(32) DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `specialty` varchar(191) DEFAULT NULL,
  `qualification` varchar(191) DEFAULT NULL,
  `license_no` varchar(64) DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `consultation_fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `availability` text DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `doctors_code_index` (`code`),
  KEY `doctors_department_id_index` (`department_id`),
  KEY `doctors_employee_id_index` (`employee_id`),
  KEY `doctors_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: document_folders
DROP TABLE IF EXISTS `document_folders`;
CREATE TABLE `document_folders` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `parent_id` bigint(20) unsigned DEFAULT NULL,
  `description` text DEFAULT NULL,
  `color` varchar(20) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `document_folders_parent_id_index` (`parent_id`),
  KEY `document_folders_created_by_index` (`created_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: document_versions
DROP TABLE IF EXISTS `document_versions`;
CREATE TABLE `document_versions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `document_id` bigint(20) unsigned NOT NULL,
  `version` int(10) unsigned NOT NULL,
  `file_name` varchar(191) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `mime_type` varchar(128) DEFAULT NULL,
  `extension` varchar(16) DEFAULT NULL,
  `size` bigint(20) unsigned NOT NULL DEFAULT 0,
  `note` varchar(255) DEFAULT NULL,
  `uploaded_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `document_versions_document_id_index` (`document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: documents
DROP TABLE IF EXISTS `documents`;
CREATE TABLE `documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `folder_id` bigint(20) unsigned DEFAULT NULL,
  `title` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `file_name` varchar(191) NOT NULL,
  `file_path` varchar(255) NOT NULL,
  `mime_type` varchar(128) DEFAULT NULL,
  `extension` varchar(16) DEFAULT NULL,
  `size` bigint(20) unsigned NOT NULL DEFAULT 0,
  `tags` text DEFAULT NULL,
  `reference` varchar(100) DEFAULT NULL,
  `expiry_date` date DEFAULT NULL,
  `is_starred` tinyint(1) NOT NULL DEFAULT 0,
  `version` int(10) unsigned NOT NULL DEFAULT 1,
  `uploaded_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `documents_folder_id_index` (`folder_id`),
  KEY `documents_title_index` (`title`),
  KEY `documents_extension_index` (`extension`),
  KEY `documents_reference_index` (`reference`),
  KEY `documents_expiry_date_index` (`expiry_date`),
  KEY `documents_is_starred_index` (`is_starred`),
  KEY `documents_uploaded_by_index` (`uploaded_by`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: draft_sale_details
DROP TABLE IF EXISTS `draft_sale_details`;
CREATE TABLE `draft_sale_details` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `draft_sale_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_variant_id` int(11) DEFAULT NULL,
  `imei_number` text DEFAULT NULL,
  `price` decimal(15,2) NOT NULL,
  `sale_unit_id` int(11) DEFAULT NULL,
  `product_pack_id` bigint(20) unsigned DEFAULT NULL,
  `pack_multiplier` double DEFAULT NULL,
  `pack_name` varchar(191) DEFAULT NULL,
  `TaxNet` decimal(15,2) DEFAULT NULL,
  `tax_method` varchar(192) DEFAULT '1',
  `discount` decimal(15,2) DEFAULT NULL,
  `discount_method` varchar(192) DEFAULT '1',
  `price_type` varchar(32) NOT NULL DEFAULT 'retail',
  `total` decimal(15,2) NOT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `draft_sale_details_draft_sale_id` (`draft_sale_id`),
  KEY `draft_sale_details_product_id` (`product_id`),
  KEY `draft_sale_details_product_variant_id` (`product_variant_id`),
  KEY `draft_sale_details_sale_unit_id` (`sale_unit_id`),
  CONSTRAINT `draft_sale_details_draft_sale_id_foreign` FOREIGN KEY (`draft_sale_id`) REFERENCES `draft_sales` (`id`),
  CONSTRAINT `draft_sale_details_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `draft_sale_details_product_variant_id_foreign` FOREIGN KEY (`product_variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `draft_sale_details_sale_unit_id_foreign` FOREIGN KEY (`sale_unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: draft_sales
DROP TABLE IF EXISTS `draft_sales`;
CREATE TABLE `draft_sales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `Ref` varchar(192) NOT NULL,
  `client_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  `tax_rate` decimal(15,2) DEFAULT 0.00,
  `TaxNet` decimal(15,2) DEFAULT 0.00,
  `discount` decimal(15,2) DEFAULT 0.00,
  `discount_Method` varchar(10) NOT NULL DEFAULT '2',
  `shipping` decimal(15,2) DEFAULT 0.00,
  `GrandTotal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `currency_id` int(11) DEFAULT NULL,
  `exchange_rate` decimal(18,6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `draft_sales_user_id` (`user_id`),
  KEY `draft_sales_client_id` (`client_id`),
  KEY `draft_sales_warehouse_id` (`warehouse_id`),
  KEY `draft_sales_currency_id_index` (`currency_id`),
  CONSTRAINT `draft_sales_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `draft_sales_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `draft_sales_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: ecommerce_clients
DROP TABLE IF EXISTS `ecommerce_clients`;
CREATE TABLE `ecommerce_clients` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
