  `ordered_at` datetime NOT NULL,
  `completed_at` datetime DEFAULT NULL,
  `priority` enum('routine','urgent','stat') NOT NULL DEFAULT 'routine',
  `status` enum('ordered','sample_collected','in_progress','completed','cancelled') NOT NULL DEFAULT 'ordered',
  `total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `lab_orders_reference_index` (`reference`),
  KEY `lab_orders_patient_id_index` (`patient_id`),
  KEY `lab_orders_doctor_id_index` (`doctor_id`),
  KEY `lab_orders_visit_id_index` (`visit_id`),
  KEY `lab_orders_ordered_at_index` (`ordered_at`),
  KEY `lab_orders_priority_index` (`priority`),
  KEY `lab_orders_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: lab_tests
DROP TABLE IF EXISTS `lab_tests`;
