-- Table: patient_visits
DROP TABLE IF EXISTS `patient_visits`;
CREATE TABLE `patient_visits` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference` varchar(32) NOT NULL,
  `patient_id` bigint(20) unsigned NOT NULL,
  `doctor_id` bigint(20) unsigned DEFAULT NULL,
  `appointment_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `visit_date` datetime NOT NULL,
  `type` enum('opd','emergency','follow_up','teleconsult') NOT NULL DEFAULT 'opd',
  `temperature` decimal(5,2) DEFAULT NULL,
  `pulse` smallint(5) unsigned DEFAULT NULL,
  `bp_systolic` smallint(5) unsigned DEFAULT NULL,
  `bp_diastolic` smallint(5) unsigned DEFAULT NULL,
  `respiratory_rate` smallint(5) unsigned DEFAULT NULL,
  `spo2` smallint(5) unsigned DEFAULT NULL,
  `weight` decimal(6,2) DEFAULT NULL,
  `height` decimal(6,2) DEFAULT NULL,
  `complaint` text DEFAULT NULL,
  `examination` text DEFAULT NULL,
  `diagnosis` text DEFAULT NULL,
  `treatment_plan` text DEFAULT NULL,
  `follow_up_date` date DEFAULT NULL,
  `status` enum('open','completed') NOT NULL DEFAULT 'completed',
  `fee` decimal(12,2) NOT NULL DEFAULT 0.00,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `patient_visits_reference_index` (`reference`),
  KEY `patient_visits_patient_id_index` (`patient_id`),
  KEY `patient_visits_doctor_id_index` (`doctor_id`),
  KEY `patient_visits_appointment_id_index` (`appointment_id`),
  KEY `patient_visits_department_id_index` (`department_id`),
  KEY `patient_visits_visit_date_index` (`visit_date`),
  KEY `patient_visits_type_index` (`type`),
  KEY `patient_visits_follow_up_date_index` (`follow_up_date`),
  KEY `patient_visits_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: patients
DROP TABLE IF EXISTS `patients`;
CREATE TABLE `patients` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `mrn` varchar(32) NOT NULL,
  `name` varchar(191) NOT NULL,
  `gender` enum('male','female','other') NOT NULL DEFAULT 'male',
  `date_of_birth` date DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `national_id` varchar(64) DEFAULT NULL,
  `blood_group` enum('A+','A-','B+','B-','AB+','AB-','O+','O-') DEFAULT NULL,
  `allergies` text DEFAULT NULL,
  `chronic_conditions` text DEFAULT NULL,
  `emergency_contact_name` varchar(191) DEFAULT NULL,
  `emergency_contact_phone` varchar(40) DEFAULT NULL,
  `emergency_contact_relation` varchar(64) DEFAULT NULL,
  `insurance_provider` varchar(191) DEFAULT NULL,
  `insurance_number` varchar(64) DEFAULT NULL,
  `insurance_expiry` date DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('active','inactive','deceased') NOT NULL DEFAULT 'active',
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `patients_mrn_unique` (`mrn`),
  KEY `patients_name_index` (`name`),
  KEY `patients_phone_index` (`phone`),
  KEY `patients_national_id_index` (`national_id`),
  KEY `patients_client_id_index` (`client_id`),
  KEY `patients_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: payment_methods
