  `image` text DEFAULT NULL,
  `note` text DEFAULT NULL,
  `stock_alert` decimal(15,2) DEFAULT 0.00,
  `weight` decimal(15,2) DEFAULT NULL,
  `length` double DEFAULT NULL,
  `width` double DEFAULT NULL,
  `height` double DEFAULT NULL,
