  KEY `warehouse_id_products` (`warehouse_id`),
  KEY `products_size_guide_id_index` (`size_guide_id`),
  KEY `products_scale_plu_index` (`scale_plu`),
  CONSTRAINT `products_brand_id_foreign` FOREIGN KEY (`brand_id`) REFERENCES `brands` (`id`),
  CONSTRAINT `products_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`),
  CONSTRAINT `products_sub_category_id_foreign` FOREIGN KEY (`sub_category_id`) REFERENCES `subcategories` (`id`),
  CONSTRAINT `products_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`),
  CONSTRAINT `products_unit_purchase_id_foreign` FOREIGN KEY (`unit_purchase_id`) REFERENCES `units` (`id`),
  CONSTRAINT `products_unit_sale_id_foreign` FOREIGN KEY (`unit_sale_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=205 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


