  `note` text DEFAULT NULL,
  `is_internal` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `protocol_request_events_request_id_index` (`request_id`),
  CONSTRAINT `protocol_request_events_request_id_foreign` FOREIGN KEY (`request_id`) REFERENCES `protocol_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: protocol_requests
DROP TABLE IF EXISTS `protocol_requests`;
CREATE TABLE `protocol_requests` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `Ref` varchar(30) DEFAULT NULL,
  `type` varchar(30) NOT NULL DEFAULT 'request',
  `subject` varchar(255) NOT NULL,
  `body` text DEFAULT NULL,
  `priority` varchar(20) NOT NULL DEFAULT 'normal',
  `status` varchar(30) NOT NULL DEFAULT 'open',
  `submitted_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `client_id` bigint(20) unsigned DEFAULT NULL,
  `submitter_name` varchar(150) DEFAULT NULL,
  `submitter_email` varchar(150) DEFAULT NULL,
  `channel` varchar(20) NOT NULL DEFAULT 'staff',
  `current_desk_id` bigint(20) unsigned DEFAULT NULL,
  `previous_desk_id` bigint(20) unsigned DEFAULT NULL,
  `assigned_to_user_id` bigint(20) unsigned DEFAULT NULL,
  `due_date` date DEFAULT NULL,
  `received_at` timestamp NULL DEFAULT NULL,
  `acknowledged_at` timestamp NULL DEFAULT NULL,
  `decided_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `closed_by_user_id` bigint(20) unsigned DEFAULT NULL,
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `protocol_requests_status_current_desk_id_index` (`status`,`current_desk_id`),
  KEY `protocol_requests_client_id_index` (`client_id`),
  KEY `protocol_requests_submitted_by_user_id_index` (`submitted_by_user_id`),
  KEY `protocol_requests_assigned_to_user_id_index` (`assigned_to_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: provider_opening_balance_payments
