  `phone` varchar(30) DEFAULT NULL,
  `date_of_birth` date DEFAULT NULL,
  `gender` enum('male','female','other') DEFAULT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(191) DEFAULT NULL,
  `state` varchar(191) DEFAULT NULL,
  `country` varchar(191) DEFAULT NULL,
  `zip_code` varchar(20) DEFAULT NULL,
  `current_company` varchar(191) DEFAULT NULL,
  `current_position` varchar(191) DEFAULT NULL,
  `current_salary` decimal(15,2) DEFAULT NULL,
  `expected_salary` decimal(15,2) DEFAULT NULL,
  `experience_years` int(11) DEFAULT NULL,
  `skills` text DEFAULT NULL,
  `education` text DEFAULT NULL,
  `resume_path` varchar(191) DEFAULT NULL,
  `photo` varchar(191) DEFAULT NULL,
  `linkedin_url` varchar(191) DEFAULT NULL,
  `portfolio_url` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `source` enum('website','referral','linkedin','job_board','agency','walk_in','other') NOT NULL DEFAULT 'website',
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `recruit_candidates_email_unique` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: recruit_interviews
DROP TABLE IF EXISTS `recruit_interviews`;
CREATE TABLE `recruit_interviews` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `application_id` bigint(20) unsigned NOT NULL,
  `type` enum('phone','video','in_person','technical','panel','group') NOT NULL DEFAULT 'in_person',
