  `status` enum('scheduled','completed','cancelled','no_show','rescheduled') NOT NULL DEFAULT 'scheduled',
  `rating` int(11) DEFAULT NULL,
  `feedback` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `recruit_interviews_application_id_foreign` (`application_id`),
  CONSTRAINT `recruit_interviews_application_id_foreign` FOREIGN KEY (`application_id`) REFERENCES `recruit_applications` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: recruit_job_categories
DROP TABLE IF EXISTS `recruit_job_categories`;
CREATE TABLE `recruit_job_categories` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
