  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: recruit_jobs
DROP TABLE IF EXISTS `recruit_jobs`;
CREATE TABLE `recruit_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(191) NOT NULL,
  `slug` varchar(191) NOT NULL,
  `category_id` bigint(20) unsigned DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `job_type` enum('full_time','part_time','contract','internship','remote') NOT NULL DEFAULT 'full_time',
  `location` varchar(191) DEFAULT NULL,
  `description` text NOT NULL,
  `requirements` text DEFAULT NULL,
  `benefits` text DEFAULT NULL,
  `salary_min` decimal(15,2) DEFAULT NULL,
  `salary_max` decimal(15,2) DEFAULT NULL,
  `currency` varchar(10) NOT NULL DEFAULT 'USD',
  `vacancies` int(11) NOT NULL DEFAULT 1,
  `status` enum('draft','open','on_hold','closed') NOT NULL DEFAULT 'draft',
  `experience_level` enum('entry','mid','senior','lead','manager') NOT NULL DEFAULT 'entry',
  `deadline` date DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `recruit_jobs_slug_unique` (`slug`),
  KEY `recruit_jobs_category_id_foreign` (`category_id`),
  CONSTRAINT `recruit_jobs_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `recruit_job_categories` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_agreement_templates
