  KEY `rental_contract_items_rental_item_id_index` (`rental_item_id`),
  KEY `rental_contract_items_returned_at_index` (`returned_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_contracts
DROP TABLE IF EXISTS `rental_contracts`;
CREATE TABLE `rental_contracts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `contract_number` varchar(32) NOT NULL,
  `rental_customer_id` bigint(20) unsigned NOT NULL,
  `client_id` int(11) NOT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `status` enum('draft','active','ended','terminated','renewed','cancelled') NOT NULL DEFAULT 'draft',
  `start_date` datetime NOT NULL,
  `end_date` datetime DEFAULT NULL,
  `rate_period` enum('hour','day','week','month','year') NOT NULL DEFAULT 'month',
  `billing_type` enum('upfront','recurring') NOT NULL DEFAULT 'recurring',
  `periods` int(10) unsigned DEFAULT NULL,
  `rent_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `tax_rate` decimal(6,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `contract_value` decimal(14,2) DEFAULT NULL,
  `deposit_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `grace_days` smallint(5) unsigned NOT NULL DEFAULT 0,
  `late_fee_type` enum('none','fixed','percent') NOT NULL DEFAULT 'none',
  `late_fee_value` decimal(14,2) NOT NULL DEFAULT 0.00,
  `late_fee_frequency` enum('once','daily') NOT NULL DEFAULT 'once',
  `terms` longtext DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `signed_name` varchar(191) DEFAULT NULL,
  `signature` varchar(191) DEFAULT NULL,
  `signed_at` datetime DEFAULT NULL,
  `activated_at` datetime DEFAULT NULL,
  `checked_out_at` datetime DEFAULT NULL,
  `returned_at` datetime DEFAULT NULL,
  `ended_at` datetime DEFAULT NULL,
  `terminated_at` datetime DEFAULT NULL,
  `termination_reason` text DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `renewed_from_id` bigint(20) unsigned DEFAULT NULL,
  `renewal_id` bigint(20) unsigned DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rental_contracts_contract_number_unique` (`contract_number`),
  KEY `rental_contracts_rental_customer_id_index` (`rental_customer_id`),
  KEY `rental_contracts_client_id_index` (`client_id`),
  KEY `rental_contracts_warehouse_id_index` (`warehouse_id`),
  KEY `rental_contracts_status_index` (`status`),
  KEY `rental_contracts_start_date_index` (`start_date`),
  KEY `rental_contracts_end_date_index` (`end_date`),
  KEY `rental_contracts_renewed_from_id_index` (`renewed_from_id`),
  KEY `rental_contracts_renewal_id_index` (`renewal_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_customer_documents
DROP TABLE IF EXISTS `rental_customer_documents`;
CREATE TABLE `rental_customer_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
