  `mime` varchar(100) DEFAULT NULL,
  `size` int(10) unsigned NOT NULL DEFAULT 0,
  `uploaded_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_customer_documents_rental_customer_id_index` (`rental_customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_customers
DROP TABLE IF EXISTS `rental_customers`;
CREATE TABLE `rental_customers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(11) NOT NULL,
  `id_type` enum('national_id','passport','driving_license','residence_permit','other') DEFAULT NULL,
