  `occupation` varchar(150) DEFAULT NULL,
  `employer` varchar(191) DEFAULT NULL,
  `employer_phone` varchar(50) DEFAULT NULL,
  `monthly_income` decimal(14,2) DEFAULT NULL,
  `emergency_name` varchar(191) DEFAULT NULL,
  `emergency_phone` varchar(50) DEFAULT NULL,
  `emergency_relation` varchar(100) DEFAULT NULL,
  `guarantor_name` varchar(191) DEFAULT NULL,
  `guarantor_phone` varchar(50) DEFAULT NULL,
  `guarantor_id_number` varchar(100) DEFAULT NULL,
  `guarantor_relation` varchar(100) DEFAULT NULL,
  `guarantor_address` varchar(255) DEFAULT NULL,
  `is_blacklisted` tinyint(1) NOT NULL DEFAULT 0,
