  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_customers_client_id_index` (`client_id`),
  KEY `rental_customers_id_number_index` (`id_number`),
  KEY `rental_customers_id_expiry_index` (`id_expiry`),
  KEY `rental_customers_is_blacklisted_index` (`is_blacklisted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_deposit_transactions
DROP TABLE IF EXISTS `rental_deposit_transactions`;
CREATE TABLE `rental_deposit_transactions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rental_contract_id` bigint(20) unsigned NOT NULL,
