  `notes` text DEFAULT NULL,
  `user_id` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_deposit_transactions_rental_contract_id_index` (`rental_contract_id`),
  KEY `rental_deposit_transactions_rental_customer_id_index` (`rental_customer_id`),
  KEY `rental_deposit_transactions_type_index` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_expenses
DROP TABLE IF EXISTS `rental_expenses`;
CREATE TABLE `rental_expenses` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rental_item_id` bigint(20) unsigned DEFAULT NULL,
