  `amount` decimal(14,2) NOT NULL,
  `expense_date` date NOT NULL,
  `payment_method_id` int(11) DEFAULT NULL,
  `account_id` int(11) DEFAULT NULL,
  `vendor` varchar(191) DEFAULT NULL,
  `reference` varchar(191) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `attachment` varchar(191) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_expenses_rental_item_id_index` (`rental_item_id`),
  KEY `rental_expenses_rental_maintenance_id_index` (`rental_maintenance_id`),
  KEY `rental_expenses_category_index` (`category`),
  KEY `rental_expenses_expense_date_index` (`expense_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_handover_items
DROP TABLE IF EXISTS `rental_handover_items`;
CREATE TABLE `rental_handover_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rental_handover_id` bigint(20) unsigned NOT NULL,
