  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_handover_items_rental_handover_id_index` (`rental_handover_id`),
  KEY `rental_handover_items_rental_contract_item_id_index` (`rental_contract_item_id`),
  KEY `rental_handover_items_rental_item_id_index` (`rental_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_handovers
DROP TABLE IF EXISTS `rental_handovers`;
CREATE TABLE `rental_handovers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `rental_contract_id` bigint(20) unsigned NOT NULL,
  `type` enum('checkout','checkin') NOT NULL,
