  `checklist` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`checklist`)),
  `photos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photos`)),
  `signature` varchar(191) DEFAULT NULL,
  `signed_name` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `charges_total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `user_id` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rental_handovers_rental_contract_id_index` (`rental_contract_id`),
  KEY `rental_handovers_type_index` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_invoices
DROP TABLE IF EXISTS `rental_invoices`;
CREATE TABLE `rental_invoices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_number` varchar(32) NOT NULL,
  `rental_contract_id` bigint(20) unsigned NOT NULL,
  `rental_customer_id` bigint(20) unsigned NOT NULL,
  `client_id` int(11) NOT NULL,
  `kind` enum('rent','charge') NOT NULL DEFAULT 'rent',
  `sequence` int(10) unsigned DEFAULT NULL,
  `description` varchar(255) DEFAULT NULL,
  `period_start` datetime DEFAULT NULL,
  `period_end` datetime DEFAULT NULL,
  `issue_date` date NOT NULL,
  `due_date` date NOT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `tax_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `late_fee` decimal(14,2) NOT NULL DEFAULT 0.00,
  `late_fee_waived` tinyint(1) NOT NULL DEFAULT 0,
  `late_fee_posted` decimal(14,2) NOT NULL DEFAULT 0.00,
  `paid_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `status` enum('unpaid','partial','paid','void') NOT NULL DEFAULT 'unpaid',
  `voided_at` datetime DEFAULT NULL,
  `void_reason` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rental_invoices_invoice_number_unique` (`invoice_number`),
  UNIQUE KEY `rental_invoices_period_unique` (`rental_contract_id`,`kind`,`sequence`),
  KEY `rental_invoices_rental_contract_id_index` (`rental_contract_id`),
  KEY `rental_invoices_rental_customer_id_index` (`rental_customer_id`),
  KEY `rental_invoices_client_id_index` (`client_id`),
  KEY `rental_invoices_due_date_index` (`due_date`),
  KEY `rental_invoices_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_items
DROP TABLE IF EXISTS `rental_items`;
CREATE TABLE `rental_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `code` varchar(64) NOT NULL,
  `name` varchar(191) NOT NULL,
  `rental_category_id` bigint(20) unsigned DEFAULT NULL,
  `type` enum('property','equipment','vehicle','other') NOT NULL DEFAULT 'equipment',
  `status` enum('available','reserved','rented','maintenance','inactive') NOT NULL DEFAULT 'available',
  `condition` enum('new','excellent','good','fair','poor','damaged') NOT NULL DEFAULT 'good',
  `warehouse_id` int(11) DEFAULT NULL,
  `quantity` int(10) unsigned NOT NULL DEFAULT 1,
  `default_period` enum('hour','day','week','month','year') NOT NULL DEFAULT 'day',
  `hourly_rate` decimal(14,2) DEFAULT NULL,
  `daily_rate` decimal(14,2) DEFAULT NULL,
  `weekly_rate` decimal(14,2) DEFAULT NULL,
  `monthly_rate` decimal(14,2) DEFAULT NULL,
  `yearly_rate` decimal(14,2) DEFAULT NULL,
  `deposit_amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `min_duration` smallint(5) unsigned DEFAULT NULL,
  `min_duration_unit` enum('hour','day','week','month','year') DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `floor` varchar(32) DEFAULT NULL,
  `area` decimal(12,2) DEFAULT NULL,
  `area_unit` varchar(16) DEFAULT NULL,
  `bedrooms` tinyint(3) unsigned DEFAULT NULL,
  `bathrooms` tinyint(3) unsigned DEFAULT NULL,
  `furnished` tinyint(1) NOT NULL DEFAULT 0,
  `amenities` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`amenities`)),
  `brand` varchar(100) DEFAULT NULL,
  `model` varchar(100) DEFAULT NULL,
  `serial_number` varchar(100) DEFAULT NULL,
  `plate_number` varchar(64) DEFAULT NULL,
  `year` smallint(5) unsigned DEFAULT NULL,
  `meter_reading` decimal(14,2) DEFAULT NULL,
  `meter_unit` varchar(16) DEFAULT NULL,
  `purchase_date` date DEFAULT NULL,
  `purchase_cost` decimal(14,2) DEFAULT NULL,
  `images` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`images`)),
  `description` text DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `show_on_website` tinyint(1) NOT NULL DEFAULT 1,
  `featured` tinyint(1) NOT NULL DEFAULT 0,
  `slug` varchar(191) DEFAULT NULL,
  `specs` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`specs`)),
  PRIMARY KEY (`id`),
  KEY `rental_items_code_index` (`code`),
  KEY `rental_items_rental_category_id_index` (`rental_category_id`),
  KEY `rental_items_type_index` (`type`),
