-- Table: rental_maintenance
DROP TABLE IF EXISTS `rental_maintenance`;
CREATE TABLE `rental_maintenance` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `number` varchar(32) NOT NULL,
  `rental_item_id` bigint(20) unsigned NOT NULL,
  `quantity` int(10) unsigned NOT NULL DEFAULT 1,
  `title` varchar(191) NOT NULL,
  `type` enum('repair','service','inspection','cleaning','other') NOT NULL DEFAULT 'repair',
  `priority` enum('low','normal','high','urgent') NOT NULL DEFAULT 'normal',
  `status` enum('open','scheduled','in_progress','completed','cancelled') NOT NULL DEFAULT 'open',
  `source` enum('manual','return','schedule','portal') NOT NULL DEFAULT 'manual',
  `rental_contract_id` bigint(20) unsigned DEFAULT NULL,
  `rental_handover_id` bigint(20) unsigned DEFAULT NULL,
  `schedule_id` bigint(20) unsigned DEFAULT NULL,
  `scheduled_start` datetime DEFAULT NULL,
  `scheduled_end` datetime DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `vendor` varchar(191) DEFAULT NULL,
  `cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `meter_reading` decimal(14,2) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `resolution` text DEFAULT NULL,
  `photos` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`photos`)),
  `cancel_reason` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rental_maintenance_number_unique` (`number`),
  KEY `rental_maintenance_rental_item_id_index` (`rental_item_id`),
  KEY `rental_maintenance_priority_index` (`priority`),
  KEY `rental_maintenance_status_index` (`status`),
  KEY `rental_maintenance_rental_contract_id_index` (`rental_contract_id`),
  KEY `rental_maintenance_schedule_id_index` (`schedule_id`),
  KEY `rental_maintenance_scheduled_start_index` (`scheduled_start`),
  KEY `rental_maintenance_employee_id_index` (`employee_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_maintenance_schedules
DROP TABLE IF EXISTS `rental_maintenance_schedules`;
CREATE TABLE `rental_maintenance_schedules` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
