  KEY `rental_maintenance_schedules_next_due_date_index` (`next_due_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rental_payment_allocations
