DROP TABLE IF EXISTS `rst_order_payments`;
CREATE TABLE `rst_order_payments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_id` int(10) unsigned NOT NULL,
  `sale_id` int(11) NOT NULL,
  `split` varchar(10) NOT NULL DEFAULT 'full',
  `shares` tinyint(3) unsigned DEFAULT NULL,
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `service_charge` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `tip` decimal(14,2) NOT NULL DEFAULT 0.00,
  `rounding` decimal(14,2) NOT NULL DEFAULT 0.00,
  `paid_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rst_order_payments_order_id_index` (`order_id`),
  KEY `rst_order_payments_sale_id_index` (`sale_id`),
  CONSTRAINT `rst_order_payments_order_id_foreign` FOREIGN KEY (`order_id`) REFERENCES `rst_orders` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_orders
DROP TABLE IF EXISTS `rst_orders`;
CREATE TABLE `rst_orders` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `ref` varchar(32) NOT NULL,
  `type` varchar(12) NOT NULL DEFAULT 'dine_in',
  `status` varchar(12) NOT NULL DEFAULT 'open',
  `table_id` int(10) unsigned DEFAULT NULL,
  `guests` smallint(5) unsigned DEFAULT NULL,
  `waiter_id` int(11) DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `customer_name` varchar(120) DEFAULT NULL,
  `customer_phone` varchar(40) DEFAULT NULL,
  `delivery_address` text DEFAULT NULL,
  `note` varchar(500) DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `sale_id` int(11) DEFAULT NULL,
  `opened_at` timestamp NULL DEFAULT NULL,
  `closed_at` timestamp NULL DEFAULT NULL,
  `cancel_reason` varchar(255) DEFAULT NULL,
  `cancelled_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `source` varchar(10) NOT NULL DEFAULT 'staff',
  `online_order_id` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rst_orders_ref_unique` (`ref`),
  UNIQUE KEY `rst_orders_online_order_id_unique` (`online_order_id`),
  KEY `rst_orders_status_type_index` (`status`,`type`),
  KEY `rst_orders_table_id_index` (`table_id`),
  KEY `rst_orders_waiter_id_index` (`waiter_id`),
  KEY `rst_orders_warehouse_id_index` (`warehouse_id`),
  KEY `rst_orders_sale_id_index` (`sale_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_reservations
DROP TABLE IF EXISTS `rst_reservations`;
CREATE TABLE `rst_reservations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(120) NOT NULL,
  `customer_phone` varchar(40) DEFAULT NULL,
  `customer_email` varchar(191) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `party_size` smallint(5) unsigned NOT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `table_id` int(10) unsigned DEFAULT NULL,
  `area_id` int(10) unsigned DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'booked',
  `source` varchar(16) NOT NULL DEFAULT 'phone',
  `note` varchar(500) DEFAULT NULL,
  `order_id` int(10) unsigned DEFAULT NULL,
  `seated_at` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `cancelled_at` datetime DEFAULT NULL,
  `cancel_reason` varchar(255) DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rst_reservations_starts_at_index` (`starts_at`),
  KEY `rst_reservations_table_id_starts_at_index` (`table_id`,`starts_at`),
  KEY `rst_reservations_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_settings
DROP TABLE IF EXISTS `rst_settings`;
CREATE TABLE `rst_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `order_prefix` varchar(16) NOT NULL DEFAULT 'RO',
  `dine_in_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `takeaway_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `delivery_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `require_guest_count` tinyint(1) NOT NULL DEFAULT 1,
  `service_charge_percent` decimal(5,2) NOT NULL DEFAULT 0.00,
  `service_charge_scope` varchar(20) NOT NULL DEFAULT 'dine_in',
  `tips_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `tip_presets` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`tip_presets`)),
  `bill_rounding` decimal(6,2) NOT NULL DEFAULT 0.00,
  `max_discount_percent` decimal(5,2) NOT NULL DEFAULT 100.00,
  `default_warehouse_id` int(11) DEFAULT NULL,
  `late_ticket_minutes` smallint(5) unsigned NOT NULL DEFAULT 20,
  `after_payment_table_status` varchar(20) NOT NULL DEFAULT 'cleaning',
  `kitchen_online_orders` varchar(20) NOT NULL DEFAULT 'on_accept',
  `receipt_header` text DEFAULT NULL,
  `receipt_footer` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `menu_times` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`menu_times`)),
  `service_product_id` int(11) DEFAULT NULL,
  `tip_product_id` int(11) DEFAULT NULL,
  `reservation_minutes` smallint(5) unsigned NOT NULL DEFAULT 90,
  `reservation_hold_minutes` smallint(5) unsigned NOT NULL DEFAULT 30,
  `no_show_minutes` smallint(5) unsigned NOT NULL DEFAULT 15,
  `max_party_size` smallint(5) unsigned NOT NULL DEFAULT 20,
  `qr_ordering_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `qr_auto_send` tinyint(1) NOT NULL DEFAULT 0,
  `online_booking_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `booking_from` varchar(5) NOT NULL DEFAULT '12:00',
  `booking_to` varchar(5) NOT NULL DEFAULT '22:00',
  `booking_slot_minutes` smallint(5) unsigned NOT NULL DEFAULT 30,
  `online_max_party` smallint(5) unsigned NOT NULL DEFAULT 8,
  `booking_notice_minutes` smallint(5) unsigned NOT NULL DEFAULT 60,
  `booking_days_ahead` smallint(5) unsigned NOT NULL DEFAULT 30,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_stations
DROP TABLE IF EXISTS `rst_stations`;
CREATE TABLE `rst_stations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(60) NOT NULL,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_tables
DROP TABLE IF EXISTS `rst_tables`;
CREATE TABLE `rst_tables` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `area_id` int(10) unsigned NOT NULL,
  `name` varchar(20) NOT NULL,
  `seats` tinyint(3) unsigned NOT NULL DEFAULT 4,
  `shape` varchar(10) NOT NULL DEFAULT 'square',
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `status` varchar(16) NOT NULL DEFAULT 'free',
  `guests` smallint(5) unsigned DEFAULT NULL,
  `seated_at` timestamp NULL DEFAULT NULL,
  `waiter_id` int(11) DEFAULT NULL,
  `merged_into_id` int(10) unsigned DEFAULT NULL,
  `status_changed_at` timestamp NULL DEFAULT NULL,
  `note` varchar(191) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `qr_token` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `rst_tables_qr_token_unique` (`qr_token`),
  KEY `rst_tables_area_id_sort_order_index` (`area_id`,`sort_order`),
  KEY `rst_tables_status_index` (`status`),
  KEY `rst_tables_merged_into_id_index` (`merged_into_id`),
  CONSTRAINT `rst_tables_area_id_foreign` FOREIGN KEY (`area_id`) REFERENCES `rst_areas` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: rst_waitlist
DROP TABLE IF EXISTS `rst_waitlist`;
CREATE TABLE `rst_waitlist` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(120) NOT NULL,
  `customer_phone` varchar(40) DEFAULT NULL,
  `party_size` smallint(5) unsigned NOT NULL,
  `quoted_minutes` smallint(5) unsigned DEFAULT NULL,
  `area_id` int(10) unsigned DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'waiting',
  `table_id` int(10) unsigned DEFAULT NULL,
  `notified_at` datetime DEFAULT NULL,
  `seated_at` datetime DEFAULT NULL,
  `left_at` datetime DEFAULT NULL,
  `added_by` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `rst_waitlist_status_created_at_index` (`status`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_commissions
DROP TABLE IF EXISTS `sale_commissions`;
CREATE TABLE `sale_commissions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `sale_id` int(11) NOT NULL,
  `sales_agent_id` int(10) unsigned NOT NULL,
  `commission_program_id` int(10) unsigned NOT NULL,
  `commission_rule_id` int(10) unsigned NOT NULL,
  `base_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `commission_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `rule_terms` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`rule_terms`)),
  `status` varchar(32) NOT NULL DEFAULT 'pending',
  `is_adjustment` tinyint(1) NOT NULL DEFAULT 0,
  `commission_receipt_id` int(10) unsigned DEFAULT NULL,
  `calculated_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sale_commissions_sale_id_index` (`sale_id`),
  KEY `sale_commissions_sales_agent_id_index` (`sales_agent_id`),
  KEY `sale_commissions_commission_program_id_index` (`commission_program_id`),
  KEY `sale_commissions_commission_rule_id_index` (`commission_rule_id`),
  KEY `sale_commissions_commission_receipt_id_index` (`commission_receipt_id`),
  CONSTRAINT `sale_commissions_commission_program_id_foreign` FOREIGN KEY (`commission_program_id`) REFERENCES `commission_programs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sale_commissions_commission_receipt_id_foreign` FOREIGN KEY (`commission_receipt_id`) REFERENCES `commission_receipts` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sale_commissions_commission_rule_id_foreign` FOREIGN KEY (`commission_rule_id`) REFERENCES `commission_rules` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sale_commissions_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE,
  CONSTRAINT `sale_commissions_sales_agent_id_foreign` FOREIGN KEY (`sales_agent_id`) REFERENCES `sales_agents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_detail_batches
DROP TABLE IF EXISTS `sale_detail_batches`;
CREATE TABLE `sale_detail_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sale_detail_id` int(10) unsigned NOT NULL,
  `product_batch_id` bigint(20) unsigned NOT NULL,
  `qty` double NOT NULL DEFAULT 0,
  `unit_price` double DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sdb_sale_detail_idx` (`sale_detail_id`),
  KEY `sdb_product_batch_idx` (`product_batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_details
DROP TABLE IF EXISTS `sale_details`;
CREATE TABLE `sale_details` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `sale_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_variant_id` int(11) DEFAULT NULL,
  `imei_number` text DEFAULT NULL,
  `price` decimal(15,3) NOT NULL,
  `sale_unit_id` int(11) DEFAULT NULL,
  `product_pack_id` bigint(20) unsigned DEFAULT NULL,
  `pack_multiplier` double DEFAULT NULL,
  `pack_name` varchar(191) DEFAULT NULL,
  `TaxNet` decimal(15,3) DEFAULT NULL,
  `tax_method` varchar(192) DEFAULT '1',
  `discount` decimal(15,3) DEFAULT NULL,
  `discount_method` varchar(192) DEFAULT '1',
  `price_type` varchar(32) NOT NULL DEFAULT 'retail',
  `warranty_date` date DEFAULT NULL,
  `guarantee_date` date DEFAULT NULL,
  `total` decimal(15,3) NOT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `details_sale_id` (`sale_id`),
  KEY `sale_product_id` (`product_id`),
  KEY `sale_product_variant_id` (`product_variant_id`),
  KEY `sales_sale_unit_id` (`sale_unit_id`),
  KEY `sale_details_date_index` (`date`),
  CONSTRAINT `sale_details_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `sale_details_product_variant_id_foreign` FOREIGN KEY (`product_variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `sale_details_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`),
  CONSTRAINT `sale_details_sale_unit_id_foreign` FOREIGN KEY (`sale_unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_documents
DROP TABLE IF EXISTS `sale_documents`;
CREATE TABLE `sale_documents` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `path` varchar(500) NOT NULL,
  `size` bigint(20) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sale_documents_sale_id` (`sale_id`),
  CONSTRAINT `sale_documents_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_return_detail_batches
DROP TABLE IF EXISTS `sale_return_detail_batches`;
CREATE TABLE `sale_return_detail_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sale_return_detail_id` int(10) unsigned NOT NULL,
  `product_batch_id` bigint(20) unsigned NOT NULL,
  `qty` double NOT NULL DEFAULT 0,
  `unit_price` double DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `srdb_sr_detail_idx` (`sale_return_detail_id`),
  KEY `srdb_product_batch_idx` (`product_batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_return_details
DROP TABLE IF EXISTS `sale_return_details`;
CREATE TABLE `sale_return_details` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_return_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `price` decimal(15,2) NOT NULL,
  `sale_unit_id` int(11) DEFAULT NULL,
  `product_pack_id` bigint(20) unsigned DEFAULT NULL,
  `pack_multiplier` double DEFAULT NULL,
  `pack_name` varchar(191) DEFAULT NULL,
  `TaxNet` decimal(15,2) DEFAULT 0.00,
  `tax_method` varchar(192) DEFAULT '1',
  `discount` decimal(15,2) DEFAULT 0.00,
  `discount_method` varchar(192) DEFAULT '1',
  `product_variant_id` int(11) DEFAULT NULL,
  `imei_number` text DEFAULT NULL,
  `quantity` decimal(12,3) NOT NULL,
  `total` decimal(15,2) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `return_id` (`sale_return_id`),
  KEY `product_id_details_returns` (`product_id`),
  KEY `sale_unit_id_return_details` (`sale_unit_id`),
  KEY `sale_return_id_product_variant_id` (`product_variant_id`),
  CONSTRAINT `sale_return_details_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `sale_return_details_product_variant_id_foreign` FOREIGN KEY (`product_variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `sale_return_details_sale_return_id_foreign` FOREIGN KEY (`sale_return_id`) REFERENCES `sale_returns` (`id`),
  CONSTRAINT `sale_return_details_sale_unit_id_foreign` FOREIGN KEY (`sale_unit_id`) REFERENCES `units` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sale_returns
DROP TABLE IF EXISTS `sale_returns`;
CREATE TABLE `sale_returns` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `time` time DEFAULT NULL,
  `Ref` varchar(192) NOT NULL,
  `sale_id` int(11) DEFAULT NULL,
  `client_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  `tax_rate` decimal(15,2) DEFAULT 0.00,
  `TaxNet` decimal(15,2) DEFAULT 0.00,
  `discount` decimal(15,2) DEFAULT 0.00,
  `shipping` decimal(15,2) DEFAULT 0.00,
  `GrandTotal` decimal(15,2) NOT NULL,
  `paid_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `payment_statut` varchar(192) NOT NULL,
  `statut` varchar(192) NOT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `currency_id` int(11) DEFAULT NULL,
  `exchange_rate` decimal(18,6) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id_returns` (`user_id`),
  KEY `sale_id_return_sales` (`sale_id`),
  KEY `client_id_returns` (`client_id`),
  KEY `warehouse_id_sale_return_id` (`warehouse_id`),
  KEY `sale_returns_currency_id_index` (`currency_id`),
  KEY `sale_returns_deleted_at_date_index` (`deleted_at`,`date`),
  CONSTRAINT `sale_returns_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `sale_returns_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`),
  CONSTRAINT `sale_returns_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `sale_returns_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sales
DROP TABLE IF EXISTS `sales`;
CREATE TABLE `sales` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `sale_uuid` char(36) DEFAULT NULL,
  `woocommerce_order_id` bigint(20) unsigned DEFAULT NULL,
  `woocommerce_order_number` varchar(64) DEFAULT NULL,
  `woocommerce_order_status` varchar(32) DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `seller_id` int(11) DEFAULT NULL,
  `sales_agent_id` int(10) unsigned DEFAULT NULL,
  `date` date NOT NULL,
  `time` time DEFAULT NULL,
  `Ref` varchar(192) NOT NULL,
  `is_pos` tinyint(1) DEFAULT 0,
  `client_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  `subscription_id` int(11) DEFAULT NULL,
  `tax_rate` decimal(15,2) DEFAULT 0.00,
  `TaxNet` decimal(15,3) DEFAULT 0.000,
  `discount` decimal(15,3) DEFAULT 0.000,
  `promotion_discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `promotion_code` varchar(64) DEFAULT NULL,
  `discount_Method` varchar(10) NOT NULL DEFAULT '2',
  `shipping` decimal(15,3) DEFAULT 0.000,
  `GrandTotal` decimal(15,3) NOT NULL DEFAULT 0.000,
  `paid_amount` decimal(15,3) NOT NULL DEFAULT 0.000,
  `payment_statut` varchar(192) NOT NULL,
  `statut` varchar(191) NOT NULL,
  `shipping_status` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `used_points` decimal(15,2) NOT NULL DEFAULT 0.00,
  `earned_points` decimal(15,2) NOT NULL DEFAULT 0.00,
  `discount_from_points` decimal(15,3) NOT NULL DEFAULT 0.000,
  `quickbooks_invoice_id` varchar(191) DEFAULT NULL,
  `quickbooks_realm_id` varchar(191) DEFAULT NULL,
  `quickbooks_synced_at` timestamp NULL DEFAULT NULL,
  `quickbooks_sync_error` varchar(2048) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `currency_id` int(11) DEFAULT NULL,
  `exchange_rate` decimal(18,6) DEFAULT NULL,
  `share_token` varchar(64) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `sales_woo_order_id_deleted_at_unique` (`woocommerce_order_id`,`deleted_at`),
  UNIQUE KEY `sales_sale_uuid_unique` (`sale_uuid`),
  UNIQUE KEY `sales_share_token_unique` (`share_token`),
  KEY `user_id_sales` (`user_id`),
  KEY `sales_sales_agent_id_index` (`sales_agent_id`),
  KEY `sale_client_id` (`client_id`),
  KEY `warehouse_id_sale` (`warehouse_id`),
  KEY `subscription_id` (`subscription_id`),
  KEY `sales_quickbooks_invoice_id_index` (`quickbooks_invoice_id`),
  KEY `sales_quickbooks_realm_id_index` (`quickbooks_realm_id`),
  KEY `sales_currency_id_index` (`currency_id`),
  KEY `seller_id_sales` (`seller_id`),
  KEY `sales_deleted_at_date_index` (`deleted_at`,`date`),
  KEY `sales_deleted_at_statut_index` (`deleted_at`,`statut`),
  KEY `sales_is_pos_warehouse_created_index` (`is_pos`,`warehouse_id`,`created_at`),
  KEY `sales_ref_index` (`Ref`),
  CONSTRAINT `sales_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `sales_sales_agent_id_foreign` FOREIGN KEY (`sales_agent_id`) REFERENCES `sales_agents` (`id`) ON DELETE SET NULL,
  CONSTRAINT `sales_subscription_id_foreign` FOREIGN KEY (`subscription_id`) REFERENCES `subscriptions` (`id`),
  CONSTRAINT `sales_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `sales_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sales_agents
DROP TABLE IF EXISTS `sales_agents`;
CREATE TABLE `sales_agents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `code` varchar(64) DEFAULT NULL,
  `name` varchar(191) NOT NULL,
  `email` varchar(192) DEFAULT NULL,
  `phone` varchar(64) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sales_agents_user_id_index` (`user_id`),
  KEY `sales_agents_code_index` (`code`),
  CONSTRAINT `sales_agents_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: salla_logs
DROP TABLE IF EXISTS `salla_logs`;
CREATE TABLE `salla_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `action` varchar(100) NOT NULL,
  `level` varchar(20) NOT NULL DEFAULT 'info',
  `message` text DEFAULT NULL,
  `context` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context`)),
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: salla_mappings
DROP TABLE IF EXISTS `salla_mappings`;
CREATE TABLE `salla_mappings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(32) NOT NULL,
  `local_id` bigint(20) unsigned NOT NULL,
  `salla_id` bigint(20) unsigned NOT NULL,
  `extra` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`extra`)),
  `synced_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `salla_mappings_type_local_unique` (`entity_type`,`local_id`),
  KEY `salla_mappings_type_remote_idx` (`entity_type`,`salla_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: salla_settings
DROP TABLE IF EXISTS `salla_settings`;
CREATE TABLE `salla_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `client_id` varchar(191) DEFAULT NULL,
  `client_secret` text DEFAULT NULL,
  `access_token` longtext DEFAULT NULL,
  `refresh_token` longtext DEFAULT NULL,
  `access_token_expires_at` timestamp NULL DEFAULT NULL,
  `refresh_token_expires_at` timestamp NULL DEFAULT NULL,
  `store_id` bigint(20) unsigned DEFAULT NULL,
  `store_name` varchar(191) DEFAULT NULL,
  `store_domain` varchar(191) DEFAULT NULL,
  `webhook_secret` text DEFAULT NULL,
  `warehouse_id` int(11) DEFAULT NULL,
  `last_sync_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: school_classes
DROP TABLE IF EXISTS `school_classes`;
CREATE TABLE `school_classes` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(32) DEFAULT NULL,
  `level` smallint(5) unsigned NOT NULL DEFAULT 0,
  `description` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `school_classes_code_index` (`code`),
  KEY `school_classes_level_index` (`level`),
  KEY `school_classes_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: school_invoice_items
DROP TABLE IF EXISTS `school_invoice_items`;
CREATE TABLE `school_invoice_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_id` bigint(20) unsigned NOT NULL,
  `fee_structure_id` bigint(20) unsigned DEFAULT NULL,
  `description` varchar(191) NOT NULL,
  `quantity` decimal(10,2) NOT NULL DEFAULT 1.00,
  `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `school_invoice_items_invoice_id_index` (`invoice_id`),
  KEY `school_invoice_items_fee_structure_id_index` (`fee_structure_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: school_invoices
DROP TABLE IF EXISTS `school_invoices`;
CREATE TABLE `school_invoices` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference` varchar(32) NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `academic_year_id` bigint(20) unsigned DEFAULT NULL,
  `class_id` bigint(20) unsigned DEFAULT NULL,
  `invoice_date` date NOT NULL,
  `due_date` date DEFAULT NULL,
  `subtotal` decimal(14,2) NOT NULL DEFAULT 0.00,
  `discount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `total` decimal(14,2) NOT NULL DEFAULT 0.00,
  `paid` decimal(14,2) NOT NULL DEFAULT 0.00,
  `status` enum('draft','unpaid','partial','paid','cancelled') NOT NULL DEFAULT 'unpaid',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `school_invoices_reference_index` (`reference`),
  KEY `school_invoices_student_id_index` (`student_id`),
  KEY `school_invoices_academic_year_id_index` (`academic_year_id`),
  KEY `school_invoices_class_id_index` (`class_id`),
  KEY `school_invoices_invoice_date_index` (`invoice_date`),
  KEY `school_invoices_due_date_index` (`due_date`),
  KEY `school_invoices_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: school_payments
DROP TABLE IF EXISTS `school_payments`;
CREATE TABLE `school_payments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference` varchar(32) NOT NULL,
  `invoice_id` bigint(20) unsigned NOT NULL,
  `student_id` bigint(20) unsigned NOT NULL,
  `paid_on` date NOT NULL,
  `amount` decimal(14,2) NOT NULL DEFAULT 0.00,
  `method` varchar(64) NOT NULL DEFAULT 'cash',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `school_payments_reference_index` (`reference`),
  KEY `school_payments_invoice_id_index` (`invoice_id`),
  KEY `school_payments_student_id_index` (`student_id`),
  KEY `school_payments_paid_on_index` (`paid_on`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: servers
DROP TABLE IF EXISTS `servers`;
CREATE TABLE `servers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `mail_mailer` varchar(191) NOT NULL DEFAULT 'smtp',
  `host` varchar(191) NOT NULL,
  `port` int(11) NOT NULL,
  `sender_name` varchar(191) NOT NULL DEFAULT 'Admin',
  `sender_email` varchar(191) DEFAULT NULL,
  `username` varchar(191) NOT NULL,
  `password` varchar(191) NOT NULL,
  `encryption` varchar(191) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: service_checklist_categories
