  PRIMARY KEY (`id`),
  KEY `service_job_items_service_job_id_index` (`service_job_id`),
  KEY `service_job_items_product_id_index` (`product_id`),
  KEY `service_job_items_type_index` (`type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: service_job_payments
DROP TABLE IF EXISTS `service_job_payments`;
