-- Table: service_jobs
DROP TABLE IF EXISTS `service_jobs`;
CREATE TABLE `service_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `Ref` varchar(192) DEFAULT NULL,
  `client_id` bigint(20) unsigned DEFAULT NULL,
