  `device_imei` varchar(191) DEFAULT NULL,
  `device_color` varchar(100) DEFAULT NULL,
  `device_password` varchar(191) DEFAULT NULL,
  `accessories` text DEFAULT NULL,
  `condition_on_arrival` text DEFAULT NULL,
