  `quote_amount` float NOT NULL DEFAULT 0,
  `quote_valid_until` date DEFAULT NULL,
  `quote_approved_at` timestamp NULL DEFAULT NULL,
  `quote_approved_by` varchar(191) DEFAULT NULL,
  `total_amount` float NOT NULL DEFAULT 0,
  `paid_amount` float NOT NULL DEFAULT 0,
  `payment_status` varchar(50) NOT NULL DEFAULT 'unpaid',
  `warranty_days` int(11) NOT NULL DEFAULT 30,
  `warranty_expires_at` date DEFAULT NULL,
  `parent_job_id` bigint(20) unsigned DEFAULT NULL,
  `quotation_id` bigint(20) unsigned DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `pickup_signature` varchar(191) DEFAULT NULL,
  `job_type` varchar(191) DEFAULT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'pending',
  `scheduled_date` datetime DEFAULT NULL,
  `scheduled_end_date` datetime DEFAULT NULL,
  `started_at` timestamp NULL DEFAULT NULL,
  `completed_at` timestamp NULL DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `service_jobs_client_id_index` (`client_id`),
  KEY `service_jobs_technician_id_index` (`technician_id`),
  KEY `service_jobs_job_type_index` (`job_type`),
  KEY `service_jobs_status_index` (`status`),
  KEY `service_jobs_scheduled_date_index` (`scheduled_date`),
  KEY `service_jobs_started_at_index` (`started_at`),
  KEY `service_jobs_completed_at_index` (`completed_at`),
  KEY `service_jobs_payment_status_index` (`payment_status`),
  KEY `service_jobs_parent_job_id_index` (`parent_job_id`),
  KEY `service_jobs_quote_approved_at_index` (`quote_approved_at`),
  KEY `service_jobs_delivered_at_index` (`delivered_at`),
  KEY `service_jobs_warranty_expires_at_index` (`warranty_expires_at`),
  KEY `service_jobs_quotation_id_index` (`quotation_id`),
  KEY `service_jobs_warehouse_id_index` (`warehouse_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


