  `restrict_master_data_by_warehouse` tinyint(1) NOT NULL DEFAULT 0,
  `customer_performance_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `product_supplier_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `require_payment_account` tinyint(1) NOT NULL DEFAULT 0,
  `enable_warehouse_letterhead` tinyint(1) NOT NULL DEFAULT 0,
  `restrict_products_by_warehouse` tinyint(1) NOT NULL DEFAULT 0,
  `virtual_combo_stock` tinyint(1) NOT NULL DEFAULT 1,
  `login_bg_color` varchar(20) DEFAULT NULL,
  `login_page_options` text DEFAULT NULL,
  `login_bg_image` varchar(191) DEFAULT NULL,
  `security_options` text DEFAULT NULL,
  `currency_position` varchar(10) NOT NULL DEFAULT 'before',
  `agt_einvoice_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `dgi_einvoice_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `portal_settings` longtext DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `currency_id` (`currency_id`),
  KEY `client_id` (`client_id`),
  KEY `warehouse_id` (`warehouse_id`),
  CONSTRAINT `settings_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `settings_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `currencies` (`id`),
  CONSTRAINT `settings_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shipment_events
DROP TABLE IF EXISTS `shipment_events`;
CREATE TABLE `shipment_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `shipment_id` int(11) NOT NULL,
  `status` varchar(30) DEFAULT NULL,
  `raw_status` varchar(191) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `location` varchar(191) DEFAULT NULL,
  `event_at` timestamp NULL DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'manual',
  `hash` varchar(40) NOT NULL,
  `payload` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`payload`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shipment_events_shipment_id_hash_unique` (`shipment_id`,`hash`),
  KEY `shipment_events_shipment_id_index` (`shipment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shipments
DROP TABLE IF EXISTS `shipments`;
CREATE TABLE `shipments` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `date` timestamp NOT NULL DEFAULT current_timestamp(),
  `Ref` varchar(192) NOT NULL,
  `sale_id` int(11) NOT NULL,
  `courier_account_id` int(11) DEFAULT NULL,
  `courier` varchar(50) DEFAULT NULL,
  `tracking_number` varchar(100) DEFAULT NULL,
  `courier_reference` varchar(100) DEFAULT NULL,
  `delivered_to` varchar(192) DEFAULT NULL,
  `shipping_address` text DEFAULT NULL,
  `destination_city` varchar(120) DEFAULT NULL,
  `status` varchar(192) NOT NULL,
  `courier_status` varchar(30) DEFAULT NULL,
  `courier_status_raw` varchar(191) DEFAULT NULL,
  `shipping_details` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `weight` decimal(10,3) DEFAULT NULL,
  `pieces` smallint(5) unsigned DEFAULT NULL,
  `cod_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `cod_status` varchar(20) DEFAULT NULL,
  `cod_remitted_at` timestamp NULL DEFAULT NULL,
  `cod_reference` varchar(120) DEFAULT NULL,
  `shipping_charges` decimal(15,2) DEFAULT NULL,
  `label_url` text DEFAULT NULL,
  `booked_at` timestamp NULL DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `returned_at` timestamp NULL DEFAULT NULL,
  `last_synced_at` timestamp NULL DEFAULT NULL,
  `courier_meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`courier_meta`)),
  `return_status` varchar(20) DEFAULT NULL,
  `return_note` varchar(500) DEFAULT NULL,
  `return_handled_at` timestamp NULL DEFAULT NULL,
  `return_handled_by` int(11) DEFAULT NULL,
  `sale_return_id` int(11) DEFAULT NULL,
  `cod_payment_id` int(11) DEFAULT NULL,
  `charges_expense_id` int(11) DEFAULT NULL,
  `sync_error` varchar(500) DEFAULT NULL,
  `sync_failures` smallint(5) unsigned NOT NULL DEFAULT 0,
  `notified_statuses` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`notified_statuses`)),
  PRIMARY KEY (`id`),
  KEY `shipment_user_id` (`user_id`),
  KEY `shipment_sale_id` (`sale_id`),
  KEY `shipments_courier_account_id_index` (`courier_account_id`),
  KEY `shipments_tracking_number_index` (`tracking_number`),
  KEY `shipments_courier_status_index` (`courier_status`),
  KEY `shipments_cod_status_index` (`cod_status`),
  KEY `shipments_return_status_index` (`return_status`),
  CONSTRAINT `shipments_sale_id_foreign` FOREIGN KEY (`sale_id`) REFERENCES `sales` (`id`),
  CONSTRAINT `shipments_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shipping_method_regions
DROP TABLE IF EXISTS `shipping_method_regions`;
CREATE TABLE `shipping_method_regions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `shipping_method_id` bigint(20) unsigned NOT NULL,
  `country` varchar(100) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shipping_method_regions_shipping_method_id_index` (`shipping_method_id`),
  KEY `shipping_method_regions_country_index` (`country`),
  CONSTRAINT `shipping_method_regions_shipping_method_id_foreign` FOREIGN KEY (`shipping_method_id`) REFERENCES `shipping_methods` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shipping_methods
DROP TABLE IF EXISTS `shipping_methods`;
CREATE TABLE `shipping_methods` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) NOT NULL,
  `price` decimal(15,2) NOT NULL DEFAULT 0.00,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `type` varchar(20) NOT NULL DEFAULT 'flat',
  `live_settings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`live_settings`)),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shopify_links
DROP TABLE IF EXISTS `shopify_links`;
CREATE TABLE `shopify_links` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` bigint(20) unsigned NOT NULL,
  `entity_type` varchar(30) NOT NULL,
  `local_id` bigint(20) unsigned NOT NULL,
  `shopify_id` varchar(64) NOT NULL,
  `shopify_handle` varchar(191) DEFAULT NULL,
  `secondary_id` varchar(64) DEFAULT NULL,
  `push_hash` varchar(64) DEFAULT NULL,
  `last_synced_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shopify_links_local_unique` (`store_id`,`entity_type`,`local_id`),
  UNIQUE KEY `shopify_links_remote_unique` (`store_id`,`entity_type`,`shopify_id`),
  KEY `shopify_links_store_id_entity_type_index` (`store_id`,`entity_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shopify_logs
DROP TABLE IF EXISTS `shopify_logs`;
CREATE TABLE `shopify_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` bigint(20) unsigned DEFAULT NULL,
  `run_id` bigint(20) unsigned DEFAULT NULL,
  `entity` varchar(30) DEFAULT NULL,
  `action` varchar(60) NOT NULL,
  `level` varchar(10) NOT NULL DEFAULT 'info',
  `message` text DEFAULT NULL,
  `context` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shopify_logs_store_id_level_index` (`store_id`,`level`),
  KEY `shopify_logs_run_id_index` (`run_id`),
  KEY `shopify_logs_created_at_index` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shopify_stores
DROP TABLE IF EXISTS `shopify_stores`;
CREATE TABLE `shopify_stores` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `shop_domain` varchar(191) NOT NULL,
  `access_token` text NOT NULL,
  `client_id` varchar(191) DEFAULT NULL,
  `client_secret` text DEFAULT NULL,
  `token_expires_at` datetime DEFAULT NULL,
  `api_version` varchar(20) NOT NULL DEFAULT '2024-10',
  `webhook_secret` varchar(191) DEFAULT NULL,
  `warehouse_id` bigint(20) unsigned DEFAULT NULL,
  `location_id` varchar(191) DEFAULT NULL,
  `currency` varchar(10) DEFAULT NULL,
  `shop_name` varchar(191) DEFAULT NULL,
  `shop_email` varchar(191) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'disconnected',
  `last_error` text DEFAULT NULL,
  `last_connected_at` datetime DEFAULT NULL,
  `price_field` varchar(30) NOT NULL DEFAULT 'price',
  `create_missing_products` tinyint(1) NOT NULL DEFAULT 1,
  `create_missing_customers` tinyint(1) NOT NULL DEFAULT 1,
  `auto_sync` tinyint(1) NOT NULL DEFAULT 0,
  `sync_interval_minutes` int(10) unsigned NOT NULL DEFAULT 60,
  `auto_sync_plan` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`auto_sync_plan`)),
  `instant_stock_push` tinyint(1) NOT NULL DEFAULT 0,
  `sync_products` tinyint(1) NOT NULL DEFAULT 1,
  `sync_inventory` tinyint(1) NOT NULL DEFAULT 1,
  `sync_customers` tinyint(1) NOT NULL DEFAULT 1,
  `sync_orders` tinyint(1) NOT NULL DEFAULT 1,
  `sync_collections` tinyint(1) NOT NULL DEFAULT 1,
  `sync_fulfillments` tinyint(1) NOT NULL DEFAULT 1,
  `last_sync_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `shopify_stores_shop_domain_unique` (`shop_domain`),
  KEY `shopify_stores_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shopify_sync_runs
DROP TABLE IF EXISTS `shopify_sync_runs`;
CREATE TABLE `shopify_sync_runs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `store_id` bigint(20) unsigned NOT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `entity` varchar(30) NOT NULL,
  `direction` varchar(10) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `dry_run` tinyint(1) NOT NULL DEFAULT 0,
  `total_items` int(10) unsigned NOT NULL DEFAULT 0,
  `processed_items` int(10) unsigned NOT NULL DEFAULT 0,
  `created_items` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_items` int(10) unsigned NOT NULL DEFAULT 0,
  `skipped_items` int(10) unsigned NOT NULL DEFAULT 0,
  `failed_items` int(10) unsigned NOT NULL DEFAULT 0,
  `percentage` int(10) unsigned NOT NULL DEFAULT 0,
  `stage` varchar(191) DEFAULT NULL,
  `cursor` text DEFAULT NULL,
  `options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`options`)),
  `last_error` text DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `cancel_requested` tinyint(1) NOT NULL DEFAULT 0,
  `heartbeat_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `shopify_sync_runs_store_id_entity_status_index` (`store_id`,`entity`,`status`),
  KEY `shopify_sync_runs_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: shopify_webhook_events
DROP TABLE IF EXISTS `shopify_webhook_events`;
CREATE TABLE `shopify_webhook_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
