  UNIQUE KEY `shopify_webhook_event_unique` (`store_id`,`event_id`),
  KEY `shopify_webhook_events_store_id_topic_status_index` (`store_id`,`topic`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: size_guides
