-- Table: store_settings
DROP TABLE IF EXISTS `store_settings`;
CREATE TABLE `store_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 1,
  `registration_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `require_invite_code` tinyint(1) NOT NULL DEFAULT 0,
  `require_admin_approval` tinyint(1) NOT NULL DEFAULT 0,
  `guest_checkout_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `store_name` varchar(191) NOT NULL DEFAULT 'StoreX',
  `theme` varchar(32) NOT NULL DEFAULT 'default',
  `logo_path` varchar(191) DEFAULT NULL,
  `favicon_path` varchar(191) DEFAULT NULL,
  `primary_color` varchar(191) NOT NULL DEFAULT '#6c5ce7',
  `secondary_color` varchar(191) NOT NULL DEFAULT '#00c2ff',
  `font_family` varchar(191) NOT NULL DEFAULT 'Poppins, system-ui, Segoe UI, Roboto, Arial, sans-serif',
  `hero_title` varchar(191) DEFAULT NULL,
  `hero_subtitle` text DEFAULT NULL,
  `hero_image_path` varchar(191) DEFAULT NULL,
  `homepage_lineup` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`homepage_lineup`)),
  `homepage_layout` varchar(32) NOT NULL DEFAULT 'default',
  `social_links` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`social_links`)),
  `menus` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`menus`)),
  `default_warehouse_id` int(11) DEFAULT NULL,
  `warehouse_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`warehouse_ids`)),
  `allow_overselling` tinyint(1) NOT NULL DEFAULT 1,
  `hide_out_of_stock` tinyint(1) NOT NULL DEFAULT 0,
  `hide_prices_for_guests` tinyint(1) NOT NULL DEFAULT 0,
  `show_stock` tinyint(1) NOT NULL DEFAULT 1,
  `currency_code` varchar(8) NOT NULL DEFAULT '$',
  `language` varchar(10) NOT NULL DEFAULT 'en',
  `store_url_path` varchar(100) DEFAULT NULL,
  `store_use_root_domain` tinyint(1) NOT NULL DEFAULT 0,
  `payment_stripe_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_cod_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_mobile_money_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_gcash_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `gcash_account_name` varchar(150) DEFAULT NULL,
  `gcash_account_number` varchar(60) DEFAULT NULL,
  `gcash_qr_path` varchar(255) DEFAULT NULL,
  `gcash_instructions` text DEFAULT NULL,
  `payment_bank_transfer_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `bank_name` varchar(150) DEFAULT NULL,
  `bank_account_name` varchar(150) DEFAULT NULL,
  `bank_account_number` varchar(60) DEFAULT NULL,
  `bank_branch` varchar(150) DEFAULT NULL,
  `bank_instructions` text DEFAULT NULL,
  `payment_cash_on_pickup_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `pickup_instructions` text DEFAULT NULL,
  `payment_razorpay_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_bkash_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_sslcommerz_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_paymob_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_myfatoorah_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_moyasar_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_xpay_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_payfast_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_ligdicash_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_dodo_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_waafipay_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `contact_email` varchar(191) DEFAULT NULL,
  `contact_phone` varchar(191) DEFAULT NULL,
  `contact_address` varchar(191) DEFAULT NULL,
  `seo_meta_title` varchar(191) DEFAULT NULL,
  `seo_meta_description` text DEFAULT NULL,
  `topbar_text_left` varchar(191) DEFAULT NULL,
  `topbar_text_right` varchar(191) DEFAULT NULL,
  `footer_text` varchar(191) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `theme_options` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`theme_options`)),
  `allow_cancellations` tinyint(1) NOT NULL DEFAULT 1,
  `return_window_days` int(10) unsigned NOT NULL DEFAULT 14,
  `auto_approve_reviews` tinyint(1) NOT NULL DEFAULT 0,
  `payment_paypal_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_paystack_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `payment_flutterwave_enabled` tinyint(1) NOT NULL DEFAULT 1,
  `cookie_consent_enabled` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: student_attendances
DROP TABLE IF EXISTS `student_attendances`;
CREATE TABLE `student_attendances` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `enrollment_id` bigint(20) unsigned DEFAULT NULL,
  `class_id` bigint(20) unsigned NOT NULL,
  `section_id` bigint(20) unsigned DEFAULT NULL,
  `subject_id` bigint(20) unsigned DEFAULT NULL,
  `attendance_date` date NOT NULL,
  `status` enum('present','absent','late','excused','half_day') NOT NULL DEFAULT 'present',
  `remarks` varchar(255) DEFAULT NULL,
  `marked_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `attendance_unique_slot` (`student_id`,`attendance_date`,`subject_id`),
  KEY `student_attendances_student_id_index` (`student_id`),
  KEY `student_attendances_enrollment_id_index` (`enrollment_id`),
  KEY `student_attendances_class_id_index` (`class_id`),
  KEY `student_attendances_section_id_index` (`section_id`),
  KEY `student_attendances_subject_id_index` (`subject_id`),
  KEY `student_attendances_attendance_date_index` (`attendance_date`),
  KEY `student_attendances_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: student_enrollments
DROP TABLE IF EXISTS `student_enrollments`;
CREATE TABLE `student_enrollments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `student_id` bigint(20) unsigned NOT NULL,
  `academic_year_id` bigint(20) unsigned NOT NULL,
  `class_id` bigint(20) unsigned NOT NULL,
  `section_id` bigint(20) unsigned DEFAULT NULL,
  `roll_number` varchar(32) DEFAULT NULL,
  `enrolled_on` date DEFAULT NULL,
  `status` enum('active','promoted','transferred','left','repeated') NOT NULL DEFAULT 'active',
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `student_enrollments_student_id_academic_year_id_unique` (`student_id`,`academic_year_id`),
  KEY `student_enrollments_student_id_index` (`student_id`),
  KEY `student_enrollments_academic_year_id_index` (`academic_year_id`),
  KEY `student_enrollments_class_id_index` (`class_id`),
  KEY `student_enrollments_section_id_index` (`section_id`),
  KEY `student_enrollments_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: students
DROP TABLE IF EXISTS `students`;
CREATE TABLE `students` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `admission_number` varchar(32) NOT NULL,
  `name` varchar(191) NOT NULL,
  `gender` enum('male','female','other') NOT NULL DEFAULT 'male',
  `date_of_birth` date DEFAULT NULL,
  `admission_date` date DEFAULT NULL,
  `blood_group` varchar(8) DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `city` varchar(100) DEFAULT NULL,
  `national_id` varchar(64) DEFAULT NULL,
  `medical_notes` text DEFAULT NULL,
  `guardian_name` varchar(191) DEFAULT NULL,
  `guardian_relation` varchar(64) DEFAULT NULL,
  `guardian_phone` varchar(40) DEFAULT NULL,
  `guardian_email` varchar(191) DEFAULT NULL,
  `guardian_occupation` varchar(100) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('active','inactive','graduated','transferred','expelled') NOT NULL DEFAULT 'active',
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `students_admission_number_unique` (`admission_number`),
  KEY `students_name_index` (`name`),
  KEY `students_admission_date_index` (`admission_date`),
  KEY `students_guardian_phone_index` (`guardian_phone`),
  KEY `students_client_id_index` (`client_id`),
  KEY `students_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: subcategories
DROP TABLE IF EXISTS `subcategories`;
CREATE TABLE `subcategories` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `category_id` int(11) NOT NULL,
  `name` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `subcategories_cat_name_unique` (`category_id`,`name`),
  CONSTRAINT `subcategories_category_id_foreign` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: subjects
DROP TABLE IF EXISTS `subjects`;
CREATE TABLE `subjects` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `code` varchar(32) DEFAULT NULL,
  `class_id` bigint(20) unsigned DEFAULT NULL,
  `type` enum('core','elective','optional') NOT NULL DEFAULT 'core',
  `credit` decimal(5,2) NOT NULL DEFAULT 1.00,
  `pass_mark` smallint(5) unsigned NOT NULL DEFAULT 40,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `subjects_code_index` (`code`),
  KEY `subjects_class_id_index` (`class_id`),
  KEY `subjects_type_index` (`type`),
  KEY `subjects_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: subscribers
DROP TABLE IF EXISTS `subscribers`;
CREATE TABLE `subscribers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(192) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: subscriptions
DROP TABLE IF EXISTS `subscriptions`;
CREATE TABLE `subscriptions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `date` date NOT NULL,
  `user_id` int(11) NOT NULL,
  `client_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  `cycle_type` varchar(192) NOT NULL,
  `total_cycles` int(11) NOT NULL,
  `billing_cycle` varchar(50) NOT NULL,
  `remaining_cycles` int(11) NOT NULL,
  `price_per_cycle` double NOT NULL,
  `price_per_unit` double NOT NULL,
  `quantity` double NOT NULL,
  `next_billing_date` date NOT NULL,
  `status` varchar(192) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id` (`user_id`),
  KEY `client_id` (`client_id`),
  KEY `product_id` (`product_id`),
  KEY `warehouse_id` (`warehouse_id`),
  CONSTRAINT `subscriptions_client_id_foreign` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`),
  CONSTRAINT `subscriptions_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `subscriptions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `subscriptions_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: sync_jobs
DROP TABLE IF EXISTS `sync_jobs`;
CREATE TABLE `sync_jobs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `warehouse_id` bigint(20) unsigned DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `total_items` int(10) unsigned NOT NULL DEFAULT 0,
  `processed_items` int(10) unsigned NOT NULL DEFAULT 0,
  `success_items` int(10) unsigned NOT NULL DEFAULT 0,
  `failed_items` int(10) unsigned NOT NULL DEFAULT 0,
  `percentage` int(10) unsigned NOT NULL DEFAULT 0,
  `stage` varchar(100) DEFAULT NULL,
  `current_product_id` bigint(20) unsigned DEFAULT NULL,
  `current_sku` varchar(255) DEFAULT NULL,
  `last_error` text DEFAULT NULL,
  `started_at` datetime DEFAULT NULL,
  `finished_at` datetime DEFAULT NULL,
  `cancel_requested` tinyint(1) NOT NULL DEFAULT 0,
  `worker_heartbeat_at` datetime DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `sync_jobs_user_id_index` (`user_id`),
  KEY `sync_jobs_warehouse_id_index` (`warehouse_id`),
  KEY `sync_jobs_status_index` (`status`),
  KEY `sync_jobs_cancel_requested_index` (`cancel_requested`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: tasks
DROP TABLE IF EXISTS `tasks`;
CREATE TABLE `tasks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `title` varchar(192) NOT NULL,
  `project_id` int(11) NOT NULL,
  `company_id` int(11) NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date NOT NULL,
  `estimated_hour` varchar(192) DEFAULT NULL,
  `task_progress` varchar(192) DEFAULT NULL,
  `summary` varchar(191) NOT NULL,
  `description` text DEFAULT NULL,
  `status` varchar(192) NOT NULL,
  `priority` varchar(191) NOT NULL,
  `note` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tasks_project_id` (`project_id`),
  KEY `tasks_company_id` (`company_id`),
  CONSTRAINT `tasks_company_id_foreign` FOREIGN KEY (`company_id`) REFERENCES `companies` (`id`),
  CONSTRAINT `tasks_project_id_foreign` FOREIGN KEY (`project_id`) REFERENCES `projects` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: tax_rates
DROP TABLE IF EXISTS `tax_rates`;
CREATE TABLE `tax_rates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(120) DEFAULT NULL,
  `country` varchar(100) NOT NULL,
  `state` varchar(100) DEFAULT NULL,
  `rate` decimal(8,3) NOT NULL DEFAULT 0.000,
  `active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tax_rates_country_index` (`country`),
  KEY `tax_rates_country_state_index` (`country`,`state`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: teachers
DROP TABLE IF EXISTS `teachers`;
CREATE TABLE `teachers` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_code` varchar(32) DEFAULT NULL,
  `name` varchar(191) NOT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `gender` enum('male','female','other') NOT NULL DEFAULT 'male',
  `phone` varchar(40) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `qualification` varchar(191) DEFAULT NULL,
  `specialization` varchar(191) DEFAULT NULL,
  `joining_date` date DEFAULT NULL,
  `salary` decimal(14,2) DEFAULT NULL,
  `address` text DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `teachers_employee_code_index` (`employee_code`),
  KEY `teachers_name_index` (`name`),
  KEY `teachers_employee_id_index` (`employee_id`),
  KEY `teachers_is_active_index` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: telegram_settings
DROP TABLE IF EXISTS `telegram_settings`;
CREATE TABLE `telegram_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `bot_token` varchar(191) DEFAULT NULL,
  `chat_id` varchar(64) DEFAULT NULL,
  `events` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`events`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: timetable_slots
DROP TABLE IF EXISTS `timetable_slots`;
CREATE TABLE `timetable_slots` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `academic_year_id` bigint(20) unsigned NOT NULL,
  `class_id` bigint(20) unsigned NOT NULL,
  `section_id` bigint(20) unsigned DEFAULT NULL,
  `subject_id` bigint(20) unsigned NOT NULL,
  `teacher_id` bigint(20) unsigned DEFAULT NULL,
  `day_of_week` enum('mon','tue','wed','thu','fri','sat','sun') NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `room` varchar(50) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `timetable_slots_academic_year_id_index` (`academic_year_id`),
  KEY `timetable_slots_class_id_index` (`class_id`),
  KEY `timetable_slots_section_id_index` (`section_id`),
  KEY `timetable_slots_subject_id_index` (`subject_id`),
  KEY `timetable_slots_teacher_id_index` (`teacher_id`),
  KEY `timetable_slots_day_of_week_index` (`day_of_week`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: transfer_detail_batches
DROP TABLE IF EXISTS `transfer_detail_batches`;
CREATE TABLE `transfer_detail_batches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_detail_id` int(10) unsigned NOT NULL,
  `source_batch_id` bigint(20) unsigned NOT NULL,
  `dest_batch_id` bigint(20) unsigned DEFAULT NULL,
  `qty` double NOT NULL DEFAULT 0,
  `unit_cost` double DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tdb_transfer_detail_idx` (`transfer_detail_id`),
  KEY `tdb_source_batch_idx` (`source_batch_id`),
  KEY `tdb_dest_batch_idx` (`dest_batch_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: transfer_detail_serials
DROP TABLE IF EXISTS `transfer_detail_serials`;
CREATE TABLE `transfer_detail_serials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `transfer_id` int(10) unsigned NOT NULL,
  `transfer_detail_id` int(10) unsigned NOT NULL,
  `product_serial_id` bigint(20) unsigned NOT NULL,
  `serial_number` varchar(191) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tds_transfer_idx` (`transfer_id`),
  KEY `tds_transfer_detail_idx` (`transfer_detail_id`),
  KEY `tds_product_serial_idx` (`product_serial_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: transfer_details
DROP TABLE IF EXISTS `transfer_details`;
CREATE TABLE `transfer_details` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transfer_id` int(11) NOT NULL,
  `product_id` int(11) NOT NULL,
  `product_variant_id` int(11) DEFAULT NULL,
  `cost` decimal(15,2) NOT NULL,
  `purchase_unit_id` int(11) DEFAULT NULL,
  `TaxNet` decimal(15,2) DEFAULT NULL,
  `tax_method` varchar(192) DEFAULT '1',
  `discount` decimal(15,2) DEFAULT NULL,
  `discount_method` varchar(192) DEFAULT '1',
  `quantity` decimal(12,3) NOT NULL,
  `total` decimal(15,2) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `batch_picks` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `transfer_id` (`transfer_id`),
  KEY `product_id_transfers` (`product_id`),
  KEY `product_variant_id_transfer` (`product_variant_id`),
  KEY `unit_sale_id_transfer` (`purchase_unit_id`),
  CONSTRAINT `transfer_details_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`),
  CONSTRAINT `transfer_details_product_variant_id_foreign` FOREIGN KEY (`product_variant_id`) REFERENCES `product_variants` (`id`),
  CONSTRAINT `transfer_details_purchase_unit_id_foreign` FOREIGN KEY (`purchase_unit_id`) REFERENCES `units` (`id`),
  CONSTRAINT `transfer_details_transfer_id_foreign` FOREIGN KEY (`transfer_id`) REFERENCES `transfers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: transfer_money
DROP TABLE IF EXISTS `transfer_money`;
CREATE TABLE `transfer_money` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `from_account_id` int(11) NOT NULL,
  `to_account_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `amount` decimal(15,2) NOT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `from_account_id` (`from_account_id`),
  KEY `to_account_id` (`to_account_id`),
  CONSTRAINT `transfer_money_from_account_id_foreign` FOREIGN KEY (`from_account_id`) REFERENCES `accounts` (`id`),
  CONSTRAINT `transfer_money_to_account_id_foreign` FOREIGN KEY (`to_account_id`) REFERENCES `accounts` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: transfers
DROP TABLE IF EXISTS `transfers`;
CREATE TABLE `transfers` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `Ref` varchar(192) NOT NULL,
  `date` date NOT NULL,
  `time` time DEFAULT NULL,
  `from_warehouse_id` int(11) NOT NULL,
  `to_warehouse_id` int(11) NOT NULL,
  `items` decimal(15,2) NOT NULL,
  `tax_rate` decimal(15,2) DEFAULT 0.00,
  `TaxNet` decimal(15,2) DEFAULT 0.00,
  `discount` decimal(15,2) DEFAULT 0.00,
  `shipping` decimal(15,2) DEFAULT 0.00,
  `GrandTotal` decimal(15,2) NOT NULL DEFAULT 0.00,
  `statut` varchar(192) NOT NULL,
  `approval_status` varchar(50) NOT NULL DEFAULT 'pending',
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_id_transfers` (`user_id`),
  KEY `from_warehouse_id` (`from_warehouse_id`),
  KEY `to_warehouse_id` (`to_warehouse_id`),
  KEY `transfers_deleted_at_date_index` (`deleted_at`,`date`),
  CONSTRAINT `transfers_from_warehouse_id_foreign` FOREIGN KEY (`from_warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `transfers_to_warehouse_id_foreign` FOREIGN KEY (`to_warehouse_id`) REFERENCES `warehouses` (`id`),
  CONSTRAINT `transfers_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: translations
DROP TABLE IF EXISTS `translations`;
CREATE TABLE `translations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `locale` varchar(191) NOT NULL,
  `key` varchar(191) NOT NULL,
  `value` text NOT NULL,
  `is_default` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `translations_locale_key_unique` (`locale`,`key`)
) ENGINE=InnoDB AUTO_INCREMENT=718192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: trays
DROP TABLE IF EXISTS `trays`;
CREATE TABLE `trays` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(192) NOT NULL,
  `description` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: units
DROP TABLE IF EXISTS `units`;
CREATE TABLE `units` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(192) NOT NULL,
  `ShortName` varchar(192) NOT NULL,
  `base_unit` int(11) DEFAULT NULL,
  `operator` char(192) DEFAULT '*',
  `operator_value` double DEFAULT 1,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `base_unit` (`base_unit`),
  CONSTRAINT `units_base_unit_foreign` FOREIGN KEY (`base_unit`) REFERENCES `units` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: user_login_sessions
DROP TABLE IF EXISTS `user_login_sessions`;
CREATE TABLE `user_login_sessions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `access_token_id` varchar(100) NOT NULL,
  `session_id` varchar(255) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `user_agent` text DEFAULT NULL,
  `logged_in_at` timestamp NULL DEFAULT NULL,
  `last_activity_at` timestamp NULL DEFAULT NULL,
  `revoked_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_login_sessions_access_token_unique` (`access_token_id`),
  KEY `user_login_sessions_user_id_index` (`user_id`),
  KEY `user_login_sessions_access_token_id_index` (`access_token_id`),
  KEY `user_login_sessions_session_id_index` (`session_id`),
  CONSTRAINT `user_login_sessions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=40 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: user_warehouse
DROP TABLE IF EXISTS `user_warehouse`;
CREATE TABLE `user_warehouse` (
  `user_id` int(11) NOT NULL,
  `warehouse_id` int(11) NOT NULL,
  KEY `user_warehouse_user_id` (`user_id`),
  KEY `user_warehouse_warehouse_id` (`warehouse_id`),
  CONSTRAINT `user_warehouse_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `user_warehouse_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `firstname` varchar(191) NOT NULL,
  `lastname` varchar(191) NOT NULL,
  `username` varchar(192) NOT NULL,
  `email` varchar(192) NOT NULL,
  `password` varchar(191) NOT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `avatar` varchar(191) DEFAULT NULL,
  `phone` varchar(192) NOT NULL,
  `role_id` int(11) NOT NULL,
  `statut` tinyint(1) NOT NULL DEFAULT 1,
  `is_all_warehouses` tinyint(1) NOT NULL DEFAULT 0,
  `record_view` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `sessions_revoked_at` datetime DEFAULT NULL,
  `pos_pin_hash` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicle_assignments
DROP TABLE IF EXISTS `vehicle_assignments`;
CREATE TABLE `vehicle_assignments` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vehicle_id` bigint(20) unsigned NOT NULL,
  `employee_id` int(11) NOT NULL,
  `start_date` datetime NOT NULL,
  `end_date` datetime DEFAULT NULL,
  `start_odometer` decimal(12,2) DEFAULT NULL,
  `end_odometer` decimal(12,2) DEFAULT NULL,
  `purpose` varchar(191) DEFAULT NULL,
  `destination` varchar(191) DEFAULT NULL,
  `status` enum('active','completed','cancelled') NOT NULL DEFAULT 'active',
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicle_assignments_vehicle_id_index` (`vehicle_id`),
  KEY `vehicle_assignments_employee_id_index` (`employee_id`),
  KEY `vehicle_assignments_start_date_index` (`start_date`),
  KEY `vehicle_assignments_status_index` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicle_fuel_logs
DROP TABLE IF EXISTS `vehicle_fuel_logs`;
CREATE TABLE `vehicle_fuel_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vehicle_id` bigint(20) unsigned NOT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `log_date` date NOT NULL,
  `odometer` decimal(12,2) NOT NULL DEFAULT 0.00,
  `quantity` decimal(10,2) NOT NULL DEFAULT 0.00,
  `unit_price` decimal(12,2) NOT NULL DEFAULT 0.00,
  `total_cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `station` varchar(191) DEFAULT NULL,
  `full_tank` tinyint(1) NOT NULL DEFAULT 1,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicle_fuel_logs_vehicle_id_index` (`vehicle_id`),
  KEY `vehicle_fuel_logs_employee_id_index` (`employee_id`),
  KEY `vehicle_fuel_logs_log_date_index` (`log_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicle_leads
DROP TABLE IF EXISTS `vehicle_leads`;
CREATE TABLE `vehicle_leads` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `type` varchar(20) NOT NULL,
  `product_id` int(11) DEFAULT NULL,
  `product_name` varchar(190) DEFAULT NULL,
  `client_id` int(11) DEFAULT NULL,
  `name` varchar(150) NOT NULL,
  `email` varchar(190) DEFAULT NULL,
  `phone` varchar(40) DEFAULT NULL,
  `message` text DEFAULT NULL,
  `preferred_date` date DEFAULT NULL,
  `preferred_time` varchar(20) DEFAULT NULL,
  `trade_plate` varchar(40) DEFAULT NULL,
  `trade_mileage` int(10) unsigned DEFAULT NULL,
  `trade_vehicle` varchar(190) DEFAULT NULL,
  `finance_deposit` decimal(14,2) DEFAULT NULL,
  `finance_term` smallint(5) unsigned DEFAULT NULL,
  `wants_finance` tinyint(1) NOT NULL DEFAULT 0,
  `has_trade_in` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'new',
  `assigned_to` int(11) DEFAULT NULL,
  `staff_note` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicle_leads_status_index` (`status`),
  KEY `vehicle_leads_type_index` (`type`),
  KEY `vehicle_leads_product_id_index` (`product_id`),
  CONSTRAINT `vehicle_leads_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicle_maintenances
DROP TABLE IF EXISTS `vehicle_maintenances`;
CREATE TABLE `vehicle_maintenances` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `vehicle_id` bigint(20) unsigned NOT NULL,
  `type` enum('service','repair','tyres','inspection','insurance','other') NOT NULL DEFAULT 'service',
  `title` varchar(191) NOT NULL,
  `service_date` date NOT NULL,
  `odometer` decimal(12,2) DEFAULT NULL,
  `cost` decimal(14,2) NOT NULL DEFAULT 0.00,
  `vendor` varchar(191) DEFAULT NULL,
  `status` enum('scheduled','in_progress','completed') NOT NULL DEFAULT 'completed',
  `next_service_date` date DEFAULT NULL,
  `next_service_odometer` decimal(12,2) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicle_maintenances_vehicle_id_index` (`vehicle_id`),
  KEY `vehicle_maintenances_type_index` (`type`),
  KEY `vehicle_maintenances_service_date_index` (`service_date`),
  KEY `vehicle_maintenances_status_index` (`status`),
  KEY `vehicle_maintenances_next_service_date_index` (`next_service_date`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicle_specs
DROP TABLE IF EXISTS `vehicle_specs`;
CREATE TABLE `vehicle_specs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` int(11) NOT NULL,
  `condition` varchar(20) NOT NULL DEFAULT 'used',
  `make` varchar(80) DEFAULT NULL,
  `model` varchar(80) DEFAULT NULL,
  `trim` varchar(120) DEFAULT NULL,
  `year` smallint(5) unsigned DEFAULT NULL,
  `mileage` int(10) unsigned DEFAULT NULL,
  `body_type` varchar(30) DEFAULT NULL,
  `fuel` varchar(30) DEFAULT NULL,
  `transmission` varchar(30) DEFAULT NULL,
  `drivetrain` varchar(30) DEFAULT NULL,
  `engine_size` decimal(4,1) DEFAULT NULL,
  `power_hp` smallint(5) unsigned DEFAULT NULL,
  `exterior_color` varchar(60) DEFAULT NULL,
  `interior` varchar(80) DEFAULT NULL,
  `doors` tinyint(3) unsigned DEFAULT NULL,
  `seats` tinyint(3) unsigned DEFAULT NULL,
  `owners` tinyint(3) unsigned DEFAULT NULL,
  `fuel_economy` varchar(40) DEFAULT NULL,
  `service_history` varchar(20) DEFAULT NULL,
  `vin` varchar(40) DEFAULT NULL,
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`features`)),
  `reservable` tinyint(1) NOT NULL DEFAULT 1,
  `is_sold` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vehicle_specs_product_id_unique` (`product_id`),
  KEY `vehicle_specs_make_model_index` (`make`,`model`),
  KEY `vehicle_specs_year_index` (`year`),
  KEY `vehicle_specs_body_type_index` (`body_type`),
  KEY `vehicle_specs_condition_index` (`condition`),
  CONSTRAINT `vehicle_specs_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: vehicles
DROP TABLE IF EXISTS `vehicles`;
CREATE TABLE `vehicles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `plate_number` varchar(64) NOT NULL,
  `vin` varchar(64) DEFAULT NULL,
  `make` varchar(64) DEFAULT NULL,
  `model` varchar(64) DEFAULT NULL,
  `year` smallint(5) unsigned DEFAULT NULL,
  `color` varchar(40) DEFAULT NULL,
  `type` enum('car','van','truck','bus','motorcycle','forklift','trailer','other') NOT NULL DEFAULT 'car',
  `status` enum('active','maintenance','inactive','sold') NOT NULL DEFAULT 'active',
  `warehouse_id` int(11) DEFAULT NULL,
  `employee_id` int(11) DEFAULT NULL,
  `fuel_type` enum('petrol','diesel','electric','hybrid','lpg','cng') NOT NULL DEFAULT 'petrol',
  `tank_capacity` decimal(8,2) DEFAULT NULL,
  `odometer` decimal(12,2) NOT NULL DEFAULT 0.00,
  `purchase_date` date DEFAULT NULL,
  `purchase_price` decimal(14,2) DEFAULT NULL,
  `insurance_provider` varchar(191) DEFAULT NULL,
  `insurance_policy` varchar(100) DEFAULT NULL,
  `insurance_expiry` date DEFAULT NULL,
  `registration_expiry` date DEFAULT NULL,
  `inspection_expiry` date DEFAULT NULL,
  `image` varchar(191) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `vehicles_plate_number_index` (`plate_number`),
  KEY `vehicles_type_index` (`type`),
  KEY `vehicles_status_index` (`status`),
  KEY `vehicles_warehouse_id_index` (`warehouse_id`),
  KEY `vehicles_employee_id_index` (`employee_id`),
  KEY `vehicles_insurance_expiry_index` (`insurance_expiry`),
  KEY `vehicles_registration_expiry_index` (`registration_expiry`),
  KEY `vehicles_inspection_expiry_index` (`inspection_expiry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: warehouse_locations
DROP TABLE IF EXISTS `warehouse_locations`;
CREATE TABLE `warehouse_locations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `warehouse_id` int(11) NOT NULL,
  `code` varchar(64) NOT NULL,
  `name` varchar(192) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `warehouse_locations_wh_code_unique` (`warehouse_id`,`code`),
  KEY `warehouse_locations_warehouse_id` (`warehouse_id`),
  CONSTRAINT `warehouse_locations_warehouse_id_foreign` FOREIGN KEY (`warehouse_id`) REFERENCES `warehouses` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: warehouses
DROP TABLE IF EXISTS `warehouses`;
CREATE TABLE `warehouses` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `name` varchar(192) NOT NULL,
  `address` varchar(500) DEFAULT NULL,
  `city` varchar(192) DEFAULT NULL,
  `mobile` varchar(192) DEFAULT NULL,
  `zip` varchar(192) DEFAULT NULL,
  `email` varchar(192) DEFAULT NULL,
  `logo` varchar(192) DEFAULT NULL,
  `invoice_footer` text DEFAULT NULL,
  `country` varchar(192) DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: webhook_deliveries
DROP TABLE IF EXISTS `webhook_deliveries`;
CREATE TABLE `webhook_deliveries` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `webhook_id` bigint(20) unsigned NOT NULL,
  `event` varchar(191) NOT NULL,
  `status` varchar(191) NOT NULL DEFAULT 'pending',
  `attempt` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `response_code` smallint(5) unsigned DEFAULT NULL,
  `payload` longtext DEFAULT NULL,
  `response_body` longtext DEFAULT NULL,
  `error_message` text DEFAULT NULL,
  `duration_ms` int(10) unsigned DEFAULT NULL,
  `delivered_at` timestamp NULL DEFAULT NULL,
  `next_attempt_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `webhook_deliveries_webhook_id_index` (`webhook_id`),
  KEY `webhook_deliveries_status_index` (`status`),
  KEY `webhook_deliveries_event_index` (`event`),
  KEY `webhook_deliveries_created_at_index` (`created_at`),
  CONSTRAINT `webhook_deliveries_webhook_id_foreign` FOREIGN KEY (`webhook_id`) REFERENCES `webhooks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: webhook_incoming_logs
DROP TABLE IF EXISTS `webhook_incoming_logs`;
CREATE TABLE `webhook_incoming_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source` varchar(191) NOT NULL,
  `event` varchar(191) DEFAULT NULL,
  `ip` varchar(64) DEFAULT NULL,
  `headers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`headers`)),
  `payload` longtext DEFAULT NULL,
  `signature_valid` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(191) NOT NULL DEFAULT 'received',
  `error_message` text DEFAULT NULL,
  `processed_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `webhook_incoming_logs_source_index` (`source`),
  KEY `webhook_incoming_logs_status_index` (`status`),
  KEY `webhook_incoming_logs_created_at_index` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: webhooks
DROP TABLE IF EXISTS `webhooks`;
CREATE TABLE `webhooks` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `url` varchar(2048) NOT NULL,
  `secret` varchar(128) NOT NULL,
  `events` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`events`)),
  `headers` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`headers`)),
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `timeout_seconds` int(10) unsigned NOT NULL DEFAULT 15,
  `last_fired_at` timestamp NULL DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `source` varchar(32) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `webhooks_is_active_index` (`is_active`),
  KEY `webhooks_user_id_index` (`user_id`),
  KEY `webhooks_source_index` (`source`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: whatsapp_logs
DROP TABLE IF EXISTS `whatsapp_logs`;
CREATE TABLE `whatsapp_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `recipient` varchar(191) NOT NULL,
  `template_key` varchar(191) DEFAULT NULL,
  `message_type` varchar(64) NOT NULL DEFAULT 'text',
  `body` text DEFAULT NULL,
  `status` varchar(32) NOT NULL DEFAULT 'pending',
  `provider_message_id` varchar(191) DEFAULT NULL,
  `error` text DEFAULT NULL,
  `meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`meta`)),
  `sent_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `whatsapp_logs_status_created_at_index` (`status`,`created_at`),
  KEY `whatsapp_logs_provider_message_id_index` (`provider_message_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: whatsapp_settings
DROP TABLE IF EXISTS `whatsapp_settings`;
CREATE TABLE `whatsapp_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `provider` varchar(64) NOT NULL DEFAULT 'meta_cloud',
  `phone_number_id` varchar(191) DEFAULT NULL,
  `business_account_id` varchar(191) DEFAULT NULL,
  `access_token` text DEFAULT NULL,
  `app_secret` text DEFAULT NULL,
  `webhook_verify_token` varchar(191) DEFAULT NULL,
  `default_country_code` varchar(8) DEFAULT NULL,
  `is_connected` tinyint(1) NOT NULL DEFAULT 0,
  `connected_at` timestamp NULL DEFAULT NULL,
  `automations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`automations`)),
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: whatsapp_templates
DROP TABLE IF EXISTS `whatsapp_templates`;
CREATE TABLE `whatsapp_templates` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(191) NOT NULL,
  `key` varchar(191) NOT NULL,
  `body` text NOT NULL,
  `language` varchar(10) NOT NULL DEFAULT 'en',
  `category` varchar(64) DEFAULT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `whatsapp_templates_key_unique` (`key`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: whatsapp_usages
DROP TABLE IF EXISTS `whatsapp_usages`;
CREATE TABLE `whatsapp_usages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `period` varchar(7) NOT NULL,
  `sent_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `whatsapp_usages_period_unique` (`period`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: woocommerce_logs
DROP TABLE IF EXISTS `woocommerce_logs`;
CREATE TABLE `woocommerce_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `action` varchar(191) NOT NULL,
  `level` varchar(191) NOT NULL DEFAULT 'info',
  `message` text DEFAULT NULL,
  `context` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context`)),
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: woocommerce_settings
DROP TABLE IF EXISTS `woocommerce_settings`;
CREATE TABLE `woocommerce_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `store_url` varchar(191) NOT NULL,
  `consumer_key` varchar(191) NOT NULL,
  `consumer_secret` varchar(191) NOT NULL,
  `wp_username` varchar(191) DEFAULT NULL,
  `wp_app_password` varchar(191) DEFAULT NULL,
  `enable_auto_sync` tinyint(1) NOT NULL DEFAULT 0,
  `auto_sync_products` tinyint(1) NOT NULL DEFAULT 0,
  `auto_sync_stock` tinyint(1) NOT NULL DEFAULT 0,
  `sync_interval` varchar(191) DEFAULT NULL,
  `last_sync_at` datetime DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  `products_per_job` int(10) unsigned NOT NULL DEFAULT 2,
  `stock_products_per_job` int(10) unsigned NOT NULL DEFAULT 3,
  `remote_index_page_cap` int(10) unsigned NOT NULL DEFAULT 500,
  `sku_search_page_cap` int(10) unsigned NOT NULL DEFAULT 10,
  `allow_alt_sku_on_lookup_conflict` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: xero_logs
DROP TABLE IF EXISTS `xero_logs`;
CREATE TABLE `xero_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `action` varchar(100) NOT NULL,
  `level` varchar(20) NOT NULL DEFAULT 'info',
  `message` text DEFAULT NULL,
  `context` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`context`)),
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: xero_mappings
DROP TABLE IF EXISTS `xero_mappings`;
CREATE TABLE `xero_mappings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `entity_type` varchar(32) NOT NULL,
  `local_id` bigint(20) unsigned NOT NULL,
  `xero_id` varchar(64) NOT NULL,
  `extra` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`extra`)),
  `synced_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp(6) NULL DEFAULT NULL,
  `updated_at` timestamp(6) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `xero_mappings_type_local_unique` (`entity_type`,`local_id`),
  KEY `xero_mappings_type_remote_idx` (`entity_type`,`xero_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: xero_settings
DROP TABLE IF EXISTS `xero_settings`;
CREATE TABLE `xero_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `client_id` varchar(191) DEFAULT NULL,
  `client_secret` text DEFAULT NULL,
  `access_token` longtext DEFAULT NULL,
  `refresh_token` longtext DEFAULT NULL,
  `access_token_expires_at` timestamp NULL DEFAULT NULL,
  `tenant_id` varchar(64) DEFAULT NULL,
  `tenant_name` varchar(191) DEFAULT NULL,
  `sales_account_code` varchar(20) NOT NULL DEFAULT '200',
  `payment_account_code` varchar(20) DEFAULT NULL,
  `auto_sync` tinyint(1) NOT NULL DEFAULT 0,
  `last_sync_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: zapier_settings
DROP TABLE IF EXISTS `zapier_settings`;
CREATE TABLE `zapier_settings` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `api_key_hash` varchar(64) DEFAULT NULL,
