) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: zatca_documents
DROP TABLE IF EXISTS `zatca_documents`;
CREATE TABLE `zatca_documents` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `source_type` varchar(191) NOT NULL,
  `source_id` bigint(20) unsigned NOT NULL,
  `invoice_number` varchar(191) DEFAULT NULL,
  `invoice_type_code` varchar(3) NOT NULL,
  `invoice_subtype` varchar(20) NOT NULL,
  `uuid` char(36) NOT NULL,
  `icv` bigint(20) unsigned NOT NULL,
  `invoice_hash` text DEFAULT NULL,
  `pih` text DEFAULT NULL,
  `qr_code` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'pending',
  `environment` varchar(20) NOT NULL DEFAULT 'sandbox',
  `invoice_xml` longtext DEFAULT NULL,
  `cleared_xml` longtext DEFAULT NULL,
  `zatca_response` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`zatca_response`)),
  `warnings` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`warnings`)),
  `errors` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`errors`)),
  `submitted_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `zatca_documents_source_type_source_id_unique` (`source_type`,`source_id`),
  KEY `zatca_documents_status_index` (`status`),
  KEY `zatca_documents_uuid_index` (`uuid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: zatca_logs
DROP TABLE IF EXISTS `zatca_logs`;
CREATE TABLE `zatca_logs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `zatca_document_id` bigint(20) unsigned DEFAULT NULL,
  `action` varchar(50) NOT NULL,
  `endpoint` varchar(191) DEFAULT NULL,
  `http_status` smallint(5) unsigned DEFAULT NULL,
  `request_meta` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`request_meta`)),
  `response_body` longtext DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `zatca_logs_zatca_document_id_index` (`zatca_document_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Table: zatca_settings
DROP TABLE IF EXISTS `zatca_settings`;
CREATE TABLE `zatca_settings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `auto_submit` tinyint(1) NOT NULL DEFAULT 1,
