  `business_category` varchar(191) DEFAULT NULL,
  `invoice_types` varchar(4) NOT NULL DEFAULT '1100',
  `crn` varchar(191) DEFAULT NULL,
  `street_name` varchar(191) DEFAULT NULL,
  `building_number` varchar(10) DEFAULT NULL,
  `plot_identification` varchar(10) DEFAULT NULL,
  `sub_division` varchar(191) DEFAULT NULL,
